-- ============================================================================
-- W20 GIFT COMPENDIUM SYNC FROM packages/core/src/catalog/gifts.data.ts
-- GENERATED. Upserts every W20 core rulebook Gift (all ranks, breeds, auspices,
-- tribes and camps) into the global compendium (campaign_id IS NULL).
--  * Existing rows keep their id and macro_config; name, level, sources, roll,
--    difficulty, costs and summary are brought in line with the core catalog.
--  * Rows that are not in the core catalog (campaign homebrew, or the six earlier
--    seed Gifts that could not be matched to the rulebook) are left untouched.
-- The app reads Gifts from the core catalog; this table only mirrors it and
-- holds campaign-specific additions.
-- ============================================================================
INSERT INTO public.compendium_gifts (
  id, campaign_id, name, level, sources, roll_attribute, roll_ability,
  default_difficulty, rage_cost, gnosis_cost, willpower_cost, system_summary
) VALUES
  ('fb7efdf5-e199-5ff5-b0b5-8b4f484a071e', NULL, 'Apecraft''s Blessings', 1, ARRAY['homid']::text[], 'wits', 'crafts', 7, 0, 0, 0, 'Spend a turn; Wits + Crafts (diff 7): each success lowers difficulty by 1 on her next roll using any manufactured tool. (W20 p. 152)'),
  ('10000000-0000-4000-8000-000000000133', NULL, 'Aura of Confidence', 1, ARRAY['shadow_lords']::text[], NULL, NULL, 6, 0, 0, 0, 'Passive: blocks attempts to find flaws in you or read your aura, though not your thoughts. (W20 p. 188)'),
  ('10000000-0000-4000-8000-000000000139', NULL, 'Balance', 1, ARRAY['stargazers']::text[], NULL, NULL, 6, 0, 0, 0, 'Permanent; no roll. Climbing difficulties drop by 3 and balance attempts succeed automatically. (W20 p. 195)'),
  ('10000000-0000-4000-8000-000000000117', NULL, 'Beast Speech', 1, ARRAY['galliard','red_talons']::text[], NULL, NULL, 6, 0, 0, 0, 'Permanent; no roll. User can talk with and understand natural animals, without altering their attitudes. (W20 p. 169)'),
  ('c893418b-0f22-568e-ba67-e7da052905ae', NULL, 'Beat of the Heart-Drum', 1, ARRAY['wendigo']::text[], 'perception', 'survival', 7, 0, 1, 0, 'Needs target item/part or tasted blood; spend 1 Gnosis; Perception + Survival (diff 7): hear the prey heartbeat 1 day per success. (W20 p. 199)'),
  ('10000000-0000-4000-8000-000000000110', NULL, 'Blur of the Milky Eye', 1, ARRAY['ragabash']::text[], 'manipulation', 'stealth', 8, 0, 0, 0, 'Manipulation + Stealth (diff 8): each success adds 1 to difficulty of Perception rolls to spot you for the scene; lost if you are noticed. (W20 p. 161)'),
  ('10000000-0000-4000-8000-000000000123', NULL, 'Breath of the Wyld', 1, ARRAY['black_furies']::text[], 'gnosis', NULL, 6, 0, 0, 0, 'Touch target; Gnosis roll (diff 5 Garou/Kin, 6 others): +1 die on Mental rolls for the scene, but +1 difficulty on their Rage rolls. (W20 p. 173)'),
  ('10000000-0000-4000-8000-000000000127', NULL, 'Brother''s Scent', 1, ARRAY['children_of_gaia']::text[], 'appearance', 'empathy', 6, 0, 1, 0, 'Spend 1 Gnosis; Appearance + Empathy (diff 6): unwary people overlook oddities until you act loudly; guards need Willpower below successes. (W20 p. 177)'),
  ('10000000-0000-4000-8000-000000000118', NULL, 'Call of the Wyld', 1, ARRAY['galliard']::text[], 'stamina', 'empathy', 6, 0, 0, 0, 'Stamina + Empathy: a howl whose range doubles per success, with Storyteller-set effects such as bonus dice or Rage for listeners. (W20 p. 169)'),
  ('10000000-0000-4000-8000-000000000143', NULL, 'Call the Breeze', 1, ARRAY['wendigo']::text[], NULL, NULL, 6, 0, 0, 0, 'No roll: summon directed cold wind; those caught lose 1 Perception die and take -1 to actions after a minute if underdressed. (W20 p. 199)'),
  ('10000000-0000-4000-8000-000000000144', NULL, 'Camouflage', 1, ARRAY['wendigo']::text[], NULL, NULL, 6, 0, 0, 0, 'Passive in wilderness: rolls to spot the Garou are at +3 difficulty. (W20 p. 199)'),
  ('ab23e14d-7392-53eb-8e93-44aa4eb230f3', NULL, 'Channeling', 1, ARRAY['stargazers']::text[], NULL, NULL, 6, 0, 0, 0, 'May spend up to 3 Rage on one action, gaining 1 extra die per point; no roll and no fixed cost. (W20 p. 195)'),
  ('50b48d40-d9ff-5188-bb91-8cf6fefa448e', NULL, 'City Running', 1, ARRAY['homid']::text[], NULL, NULL, 6, 1, 0, 0, 'Spend 1 Rage, no roll: for the scene, urban climbing at full speed and city Athletics rolls get -2 difficulty. (W20 p. 152)'),
  ('10000000-0000-4000-8000-000000000130', NULL, 'Control Simple Machine', 1, ARRAY['glass_walkers']::text[], 'manipulation', 'crafts', 7, 0, 0, 1, 'Spend 1 Willpower; Manipulation + Crafts (diff 7): operate simple mechanisms like levers, bolts and pulleys until scene end. (W20 p. 182)'),
  ('10000000-0000-4000-8000-000000000124', NULL, 'Cooking', 1, ARRAY['bone_gnawers']::text[], 'wits', 'survival', 6, 0, 0, 0, 'Wits + Survival (diff 6): the improvised mush feeds one person per success. (W20 p. 174)'),
  ('10000000-0000-4000-8000-000000000104', NULL, 'Create Element', 1, ARRAY['metis']::text[], 'gnosis', NULL, 6, 0, 1, 0, 'Spend 1 Gnosis; Gnosis roll: conjure ~1 cubic ft of fire, air, earth or water per success (max 100 lbs, 60 ft); fire deals up to 3 levels. (W20 p. 155)'),
  ('3c49d237-da61-5115-bb9c-d86afcf27d86', NULL, 'Desperate Strength', 1, ARRAY['bone_gnawers']::text[], NULL, NULL, 6, 0, 0, 0, 'On a Feat of Strength, add 1 die for each bashing health level willingly suffered; no separate roll or cost. (W20 p. 174)'),
  ('10000000-0000-4000-8000-000000000131', NULL, 'Diagnostics', 1, ARRAY['glass_walkers']::text[], NULL, NULL, 6, 0, 1, 0, 'Auto-diagnose broken tech; spend 1 Gnosis to enlist its spirit, halving repair time and required successes. (W20 p. 182)'),
  ('d652c2f1-5b75-595d-b2c9-51a41f2e9727', NULL, 'Dream of a Thousand Cranes', 1, ARRAY['hakken']::text[], 'charisma', 'occult', 6, 0, 1, 0, 'Spend 1 Gnosis and a turn folding origami; Charisma + Occult: gain 1 one-use bonus die per success for the scene. (W20 p. 189)'),
  ('10000000-0000-4000-8000-000000000137', NULL, 'Eye of the Falcon', 1, ARRAY['silver_fangs']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis: for the scene, long-range attacks and sight-based Perception rolls get -1 difficulty. (W20 p. 193)'),
  ('f0082bf3-8dc9-54f0-a525-1f553e2b4f71', NULL, 'Eye of the Hunter', 1, ARRAY['red_talons']::text[], 'perception', 'primal_urge', 7, 0, 0, 0, 'Perception + Primal-Urge (diff 7): reveals a visible group''s strongest, weakest and leader; +1 attack die against the weakest for the scene. (W20 p. 185)'),
  ('eb60df21-4823-59e3-b019-b3df5dcb7b68', NULL, 'Faerie Light', 1, ARRAY['fianna']::text[], 'wits', 'enigmas', 6, 0, 0, 0, 'Wits + Enigmas (diff 6): torch-bright light orb in line of sight, moves 10 ft/turn on command, lasts the scene. (W20 p. 178)'),
  ('2805e1c4-bc6b-55bb-a4be-834ad374f27c', NULL, 'Fair Path', 1, ARRAY['hakken']::text[], 'charisma', 'etiquette', 6, 0, 0, 0, 'Hand in clean water; Charisma + Etiquette: +1 die to Appearance-linked rolls until scene end. (W20 p. 189)'),
  ('342a0da3-453c-5a16-bc79-2733df0ddf27', NULL, 'Falcon''s Grasp', 1, ARRAY['silver_fangs']::text[], NULL, NULL, 6, 1, 0, 0, 'Spend 1 Rage: for the scene, count Strength as +3 for grappling and jaw-lock maneuvers (not damage). (W20 p. 193)'),
  ('10000000-0000-4000-8000-000000000122', NULL, 'Falling Touch', 1, ARRAY['ahroun','stargazers']::text[], 'willpower', NULL, 6, 0, 0, 0, 'Willpower roll vs foe Stamina + Athletics: 1 success knocks target prone; free by touch, or pay 1 Willpower/Rage to add to an attack. (W20 p. 170)'),
  ('3bd6299f-9c32-5c62-8b19-576e1eb43589', NULL, 'Fangs of Judgment', 1, ARRAY['philodox']::text[], NULL, NULL, 6, 0, 0, 1, 'Spend 1 Willpower, no roll: for a day, natural weapons deal +2 damage dice to Wyrm-corrupted beings (not native Banes). (W20 p. 166)'),
  ('10000000-0000-4000-8000-000000000134', NULL, 'Fatal Flaw', 1, ARRAY['shadow_lords']::text[], 'perception', 'empathy', 6, 0, 0, 0, 'One turn of focus; Perception + Empathy vs target''s Wits + Subterfuge: gain +1 damage die against that target; extra successes only inform. (W20 p. 188)'),
  ('10000000-0000-4000-8000-000000000107', NULL, 'Hare''s Leap', 1, ARRAY['lupus','fianna']::text[], 'strength', 'athletics', 7, 0, 0, 0, 'Reflexive Strength + Athletics (diff 7): double jump distance for the scene, or triple for one turn by spending 1 Willpower. (W20 p. 158)'),
  ('10000000-0000-4000-8000-000000000136', NULL, 'Heavens'' Guidance', 1, ARRAY['silent_striders']::text[], NULL, NULL, 6, 0, 0, 0, 'Passive: always know north and the route you travelled. (W20 p. 191)'),
  ('10000000-0000-4000-8000-000000000108', NULL, 'Heightened Senses', 1, ARRAY['lupus','galliard','black_furies']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis for a scene: Perception difficulty -2 (-3 in animal forms), Perception + Primal-Urge feats; animal forms +1 Primal-Urge die. (W20 p. 158)'),
  ('69ac7d00-7205-5e1a-b2f0-6f2382cb06f7', NULL, 'Hidden Killer', 1, ARRAY['red_talons']::text[], 'intelligence', 'larceny', 7, 0, 0, 0, 'Touch or lick each corpse; Intelligence + Larceny (diff 7): wounds look like blade injuries and your forensic traces vanish. (W20 p. 185)'),
  ('8fa60785-f4d3-553e-887c-a23f3b6214af', NULL, 'Ice Echo', 1, ARRAY['wendigo']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis: create an intangible mirror-image duplicate within 100 ft; telling it apart takes Perception + Enigmas vs the user''s Gnosis. (W20 p. 200)'),
  ('5d77c8d2-2f76-5a8c-86a6-b1fc1c492e51', NULL, 'Infectious Laughter', 1, ARRAY['ragabash']::text[], 'manipulation', 'expression', 6, 0, 0, 0, 'Mock the situation then laugh; Manipulation + Expression: listeners drop their anger and forget its cause until reminded. (W20 p. 161)'),
  ('10000000-0000-4000-8000-000000000121', NULL, 'Inspiration', 1, ARRAY['ahroun','silver_fangs']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis, no roll: every ally except the user gets 1 temporary Willpower that vanishes at scene end if unspent. (W20 p. 171)'),
  ('2ab49589-0baf-5475-bd66-80a34086ee2a', NULL, 'Iron Resolve', 1, ARRAY['stargazers']::text[], NULL, NULL, 6, 0, 0, 1, 'Once per scene, spend 1 Willpower: get 2 automatic successes instead of 1 on an action. (W20 p. 195)'),
  ('5cef17d0-61b3-5bc9-adbe-267e229f7870', NULL, 'Jam Weapon', 1, ARRAY['children_of_gaia']::text[], 'willpower', NULL, 6, 0, 1, 0, 'Spend 1 Gnosis; Willpower roll vs the highest Willpower among armed people in earshot: manufactured weapons fail for 1 turn per success. (W20 p. 177)'),
  ('10000000-0000-4000-8000-000000000138', NULL, 'Lambent Flame', 1, ARRAY['silver_fangs']::text[], NULL, NULL, 6, 0, 0, 1, 'Spend 1 Willpower, no roll: silver glow lights 100 ft around you for the scene and attacks against you get +1 difficulty. (W20 p. 193)'),
  ('27a9e405-f848-55b6-aeea-f27f55adc3bb', NULL, 'Liar''s Face', 1, ARRAY['ragabash']::text[], 'charisma', 'subterfuge', 7, 0, 0, 1, 'After a true statement, spend 1 Willpower; Charisma + Subterfuge (diff 7): humans disbelieve it; supernaturals with lower Willpower too. (W20 p. 161)'),
  ('d133c7ed-6986-5a43-bc83-1ade0ae36e0f', NULL, 'Lightning Reflexes', 1, ARRAY['get_of_fenris']::text[], NULL, NULL, 6, 0, 0, 1, 'Reflexively spend 1 Willpower; for a day, switching to a defensive action costs no Willpower roll or point. (W20 p. 180)'),
  ('9fd8142b-cbc0-512d-bb9f-86c7ba97873c', NULL, 'Man''s Skin', 1, ARRAY['black_furies']::text[], 'charisma', 'subterfuge', 7, 0, 0, 0, 'Charisma + Subterfuge (diff 7): appear as the opposite sex for 1 scene per success or until shapeshifting; survives light touch. (W20 p. 173)'),
  ('10000000-0000-4000-8000-000000000101', NULL, 'Master of Fire', 1, ARRAY['homid','get_of_fenris']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis; no roll. Fire deals only bashing to the user for the scene. (W20 p. 152)'),
  ('140f1852-d27f-58a9-9de8-69a376d75a08', NULL, 'Mercy', 1, ARRAY['children_of_gaia']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis: all damage from your own body counts as bashing for the scene; foes knocked out rather than killed. (W20 p. 177)'),
  ('10000000-0000-4000-8000-000000000119', NULL, 'Mindspeak', 1, ARRAY['galliard']::text[], 'manipulation', 'expression', 6, 0, 0, 1, 'Spend 1 Willpower per participant (whole pack for 1); Manipulation + Expression if unwilling: shared dream link, bodies at -2 dice. (W20 p. 169)'),
  ('10000000-0000-4000-8000-000000000113', NULL, 'Mother''s Touch', 1, ARRAY['theurge','children_of_gaia']::text[], 'intelligence', 'empathy', 6, 0, 1, 0, 'Spend 1 Gnosis; Intelligence + Empathy: each success heals 1 health level on another living target; extra Gnosis mends fresh scars. (W20 p. 164)'),
  ('10000000-0000-4000-8000-000000000111', NULL, 'Open Seal', 1, ARRAY['ragabash']::text[], 'gnosis', NULL, 6, 0, 0, 0, 'Gnosis roll (diff = local Gauntlet): opens almost any closed or locked device; magically sealed objects need 1 Gnosis spent first. (W20 p. 161)'),
  ('0c9a9286-9ad3-5859-ba84-1d422d32880c', NULL, 'Pack Tactics', 1, ARRAY['ahroun']::text[], NULL, NULL, 6, 0, 0, 1, 'Spend 1 Willpower before a Pack Tactics maneuver; split extra dice equal to Leadership among participants, as evenly as possible. (W20 p. 171)'),
  ('2c179843-ca97-5259-a40c-d1d9d8099ffd', NULL, 'Perfect Recall', 1, ARRAY['galliard']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis, no roll: recall any single detail from the character''s whole life exactly. (W20 p. 169)'),
  ('10000000-0000-4000-8000-000000000102', NULL, 'Persuasion', 1, ARRAY['homid','philodox','fianna','glass_walkers']::text[], 'charisma', 'subterfuge', 7, 0, 0, 0, 'Charisma + Subterfuge (diff 7): -1 difficulty to every social roll this scene, and successful social rolls hit unusually hard. (W20 p. 153)'),
  ('fd1a0f43-b118-509b-8084-e42ea816f15e', NULL, 'Plug and Play', 1, ARRAY['glass_walkers']::text[], NULL, NULL, 6, 0, 0, 1, 'Spend 1 Willpower, no roll: for a day, any computer you use can interface with any digital device or network regardless of hardware. (W20 p. 183)'),
  ('34b33e30-a146-5b55-be33-86be53c89e5c', NULL, 'Predator''s Arsenal', 1, ARRAY['lupus']::text[], NULL, NULL, 6, 0, 0, 0, 'One turn of focus, no roll: gain bite and claw attacks in Homid form for the scene, dealing lethal damage and concealable. (W20 p. 159)'),
  ('f7a26538-0061-56e5-9cd0-cebc849cb78b', NULL, 'Prey Mind', 1, ARRAY['lupus']::text[], 'wits', 'primal_urge', 6, 0, 0, 0, 'Wits + Primal-Urge (diff 7 wild, 9 urban): +1 die per success to evasion, flight and hiding pools for the scene. (W20 p. 159)'),
  ('10000000-0000-4000-8000-000000000105', NULL, 'Primal Anger', 1, ARRAY['metis']::text[], NULL, NULL, 6, 0, 0, 0, 'No roll: once per scene take 1 aggravated health level to gain 3 Rage, even beyond permanent Rage. (W20 p. 156)'),
  ('4536e8b8-78ce-55b3-a809-7fb120c2553a', NULL, 'Rat Head', 1, ARRAY['metis']::text[], 'dexterity', 'athletics', 7, 0, 1, 0, 'Spend 1 Gnosis; Dexterity + Athletics (diff 7): scene-long: pass any opening your head fits through, moving at walking pace. (W20 p. 156)'),
  ('10000000-0000-4000-8000-000000000120', NULL, 'Razor Claws', 1, ARRAY['ahroun','get_of_fenris']::text[], NULL, NULL, 6, 1, 0, 0, 'Spend 1 Rage and a full turn sharpening: claw attacks gain +2 damage dice and -1 difficulty for the scene. (W20 p. 171)'),
  ('10000000-0000-4000-8000-000000000115', NULL, 'Resist Pain', 1, ARRAY['philodox','children_of_gaia','get_of_fenris','wendigo']::text[], NULL, NULL, 6, 0, 0, 1, 'Spend 1 Willpower; no roll. Wound penalties are ignored for the scene. (W20 p. 166)'),
  ('10000000-0000-4000-8000-000000000125', NULL, 'Resist Toxin', 1, ARRAY['bone_gnawers','fianna']::text[], NULL, NULL, 6, 0, 0, 0, 'Passive, toggleable: immune to mundane poisons and +3 dice to resist Wyrm-enhanced toxins. (W20 p. 174)'),
  ('10000000-0000-4000-8000-000000000112', NULL, 'Scent of Running Water', 1, ARRAY['ragabash','red_talons']::text[], NULL, NULL, 6, 0, 0, 0, 'Passive: tracking rolls against you get +2 difficulty; Ragabash may suppress it at will. (W20 p. 161)'),
  ('1c434f17-d59f-5c9b-a7cb-c60f418a17a1', NULL, 'Scent of Sweet Honey', 1, ARRAY['bone_gnawers']::text[], 'wits', 'subterfuge', 7, 0, 1, 0, 'Spend 1 Gnosis; Wits + Subterfuge (diff 7): a target you touched within the hour is swarmed by insects, -1 to all actions 1 hr/success. (W20 p. 174)'),
  ('0c03460f-0b02-52cc-ac8c-8aa95682cd0e', NULL, 'Scent of the True Form', 1, ARRAY['philodox']::text[], 'perception', 'primal_urge', 6, 0, 0, 0, 'Perception + Primal-Urge (diff 6): 1 success human/animal, 2 supernatural, 4 mage/ghoul/fomor; Kin and Garou are automatic. (W20 p. 166)'),
  ('58ee7a30-1236-5855-8484-755069f5bd22', NULL, 'See Past the Skin', 1, ARRAY['skin_dancer']::text[], 'gnosis', NULL, 6, 0, 0, 0, 'Gnosis roll (diff 6), one success needed: spot the mystic patchwork marking a Skin Dancer in Crinos form. (W20 p. 199)'),
  ('dd88dbeb-855d-554f-bdfc-a91ca6c9dc6e', NULL, 'Seizing the Edge', 1, ARRAY['shadow_lords']::text[], NULL, NULL, 6, 0, 0, 0, 'Permanent, no roll: you win ties in opposed rolls; using it for more than one tie per scene costs 1 Gnosis each extra. (W20 p. 188)'),
  ('10000000-0000-4000-8000-000000000141', NULL, 'Sense Magic', 1, ARRAY['uktena']::text[], 'perception', 'enigmas', 6, 0, 0, 0, 'Perception + Enigmas: detect magic within 20 ft per success; 3+ successes give a hint of its type. (W20 p. 196)'),
  ('10000000-0000-4000-8000-000000000109', NULL, 'Sense Prey', 1, ARRAY['lupus']::text[], 'perception', 'primal_urge', 6, 0, 0, 0, 'Perception + Primal-Urge (diff 5 wild, 7 urban): a success reveals where enough game lives to feed a big pack for a day. (W20 p. 159)'),
  ('10000000-0000-4000-8000-000000000106', NULL, 'Sense Wyrm', 1, ARRAY['metis','theurge','black_furies','silent_striders','silver_fangs','stargazers','uktena']::text[], 'perception', 'occult', 6, 0, 0, 0, 'Perception + Occult, with active concentration: detects Wyrm taint nearby; harder for faint or old traces. (W20 p. 156)'),
  ('1ee1b745-10fb-5153-9aac-dbda65efe26b', NULL, 'Shadow Weaving', 1, ARRAY['shadow_lords']::text[], 'dexterity', 'occult', 7, 0, 1, 0, 'Spend 1 Gnosis; Dexterity + Occult (diff 7): manipulate shadows within 100 yards for the scene, -1 difficulty on Stealth and Intimidation. (W20 p. 188)'),
  ('71ea3918-252e-595d-8789-4f6494305e13', NULL, 'Shed', 1, ARRAY['metis']::text[], 'dexterity', 'primal_urge', 7, 0, 0, 0, 'Dexterity + Primal-Urge (diff 7): on success you leave behind a patch of hide and slip out of grapples or restraints. (W20 p. 156)'),
  ('5f2c1695-44ed-5e4b-93f0-b9ca9a375f53', NULL, 'Sheng-Nong''s Eyes', 1, ARRAY['boli_zousizhe']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis: one bonus action now; scene-long, attack unseen foes and ignore visibility and off-hand penalties. (W20 p. 183)'),
  ('10000000-0000-4000-8000-000000000142', NULL, 'Shroud', 1, ARRAY['uktena']::text[], 'gnosis', NULL, 6, 0, 1, 0, 'Spend 1 Gnosis; Gnosis roll: each success darkens a 10-ft cube you alone see through; night-vision powers defeat it. (W20 p. 197)'),
  ('f06e88da-0c62-5d64-a909-1d420cce65e4', NULL, 'Silence', 1, ARRAY['silent_striders']::text[], NULL, NULL, 6, 0, 0, 0, 'Passive: +2 dice to all Dexterity + Stealth rolls. (W20 p. 191)'),
  ('10000000-0000-4000-8000-000000000103', NULL, 'Smell of Man', 1, ARRAY['homid']::text[], NULL, NULL, 6, 0, 0, 0, 'Passive: wild animals get -2 dice against you and tend to flee; pets and guard dogs treat you as friendly. (W20 p. 153)'),
  ('10000000-0000-4000-8000-000000000135', NULL, 'Speed of Thought', 1, ARRAY['silent_striders','kucha_ekundu']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis: running speed is doubled until the scene ends. (W20 p. 191)'),
  ('c44b0194-f625-5c2a-a868-73434aa9e1af', NULL, 'Spirit of the Lizard', 1, ARRAY['uktena']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis, no roll: cling to any surface at walking pace for the scene; harder action needs reflexive Stamina + Athletics (diff 7). (W20 p. 197)'),
  ('b29ffe5c-03ef-58b7-8035-0ecbea7561b7', NULL, 'Spirit Snare', 1, ARRAY['theurge']::text[], 'intelligence', 'occult', 8, 0, 1, 0, 'Spend 1 Gnosis; Intelligence + Occult (diff 8) attack on a spirit within 30 ft: its Willpower -2 for combat this scene; no stacking. (W20 p. 164)'),
  ('10000000-0000-4000-8000-000000000114', NULL, 'Spirit Speech', 1, ARRAY['theurge','uktena']::text[], NULL, NULL, 6, 0, 0, 0, 'Permanent: can understand and talk with any spirit; does not alter how the spirit feels about her. (W20 p. 164)'),
  ('f62719e3-31cc-5bf9-9ca3-10456f950d7b', NULL, 'Spur Claws', 1, ARRAY['ahroun']::text[], NULL, NULL, 6, 1, 0, 0, 'Spend 1 Rage: next successful claw hit lodges barbed spurs, giving victim +2 difficulty on all actions until pulled out (a turn). (W20 p. 171)'),
  ('838046c2-1020-5987-99ee-b6f60a29e748', NULL, 'Trash is Treasure', 1, ARRAY['bone_gnawers']::text[], 'wits', 'crafts', 6, 0, 0, 0, 'Wits + Crafts on broken item: works self-powered 1 turn per success; spend 1 Willpower for a day, but needs real fuel or ammo then. (W20 p. 175)'),
  ('732b53da-c2fb-5062-ba60-0233ea5ab27e', NULL, 'Trick Shot', 1, ARRAY['glass_walkers']::text[], NULL, NULL, 6, 0, 0, 0, 'Permanent; add permanent Glory to pools for outlandish rifle or pistol trick shots; cannot directly injure targets. (W20 p. 183)'),
  ('10000000-0000-4000-8000-000000000116', NULL, 'Truth of Gaia', 1, ARRAY['philodox']::text[], 'intelligence', 'empathy', 6, 0, 0, 0, 'Intelligence + Empathy: learn which spoken statements are true or false, but not the real truth behind a lie. (W20 p. 166)'),
  ('10000000-0000-4000-8000-000000000128', NULL, 'Two Tongues', 1, ARRAY['fianna']::text[], NULL, NULL, 6, 0, 0, 1, 'Spend 1 Willpower, no roll: hold two separate conversations at once this scene; doubters need Perception + Alertness (diff 9). (W20 p. 179)'),
  ('c28ef148-0260-5b79-92ca-7808bcbc842a', NULL, 'Umbral Tether', 1, ARRAY['theurge']::text[], NULL, NULL, 6, 0, 0, 0, 'No roll: creates a cord back to the Gauntlet crossing point; pay 1 Gnosis per full day in the Umbra to keep it from decaying. (W20 p. 164)'),
  ('10000000-0000-4000-8000-000000000129', NULL, 'Visage of Fenris', 1, ARRAY['get_of_fenris']::text[], 'charisma', 'intimidation', 6, 0, 0, 0, 'Charisma + Intimidation: allies get -1 social difficulty, foes -1 initiative for a scene; higher ranks need double the rank gap in hits. (W20 p. 180)'),
  ('f616c42e-e6bb-5faf-915d-5674111208b4', NULL, 'Visions of Duat', 1, ARRAY['silent_striders']::text[], 'perception', 'occult', 7, 0, 1, 0, 'Spend 1 Gnosis; Perception + Occult (diff 7): perceive ghosts for the scene (haunts need another roll); a botch attracts hostile shades. (W20 p. 191)'),
  ('f592dc86-7033-58e2-840b-1c86ad10bec6', NULL, 'Whisper Catching', 1, ARRAY['shadow_lords']::text[], NULL, NULL, 6, 0, 0, 1, 'Spend 1 Willpower; no roll. For the scene, every whisper within 200 ft is heard clearly. (W20 p. 189)'),
  ('10000000-0000-4000-8000-000000000132', NULL, 'Wolf at the Door', 1, ARRAY['red_talons']::text[], 'charisma', 'primal_urge', 6, 0, 0, 0, 'Charisma + Primal-Urge vs target''s Willpower: a human dreads wilderness and leaving home 1 day per success; howl hits Rage-many humans. (W20 p. 185)'),
  ('70aacfb7-a499-5f17-aa99-ca721203d77a', NULL, 'Wyld Resurgence', 1, ARRAY['black_furies']::text[], NULL, NULL, 6, 0, 1, 0, 'Concentrate a turn and spend 1 Gnosis: heal 3 bashing or 2 lethal; add 1 Willpower to heal 1 aggravated instead; silver damage excluded. (W20 p. 173)'),
  ('b247a579-b702-5c86-8b2c-2499d4156b47', NULL, 'Axis Mundi', 2, ARRAY['lupus','silent_striders']::text[], NULL, NULL, 6, 0, 0, 0, 'Permanent: always knows her heading while in the Gaia Realm; no roll or cost. (W20 p. 159)'),
  ('c4af50d7-1ba4-5a34-adf1-546a2d4daa30', NULL, 'Battle Mandala', 2, ARRAY['theurge']::text[], 'intelligence', 'occult', 7, 0, 1, 0, 'Spend 1 Gnosis; Intelligence + Occult (diff 7): 50 ft radius per success where spirits (not pack totem) lose 1 Essence per turn. (W20 p. 164)'),
  ('1f4bdf40-6afa-53bc-82c6-f45b1b848130', NULL, 'Beastmind', 2, ARRAY['red_talons']::text[], 'manipulation', 'empathy', 6, 0, 0, 0, 'Manipulation + Empathy vs Willpower: target acts like an animal 1 minute per success; 1 Rage on ordinary humans makes it days. (W20 p. 186)'),
  ('4f56a8eb-597b-510c-a350-a31ad11f0fbc', NULL, 'Between the Cracks', 2, ARRAY['bone_gnawers']::text[], 'wits', 'streetwise', 5, 0, 0, 1, 'Spend 1 Willpower; Wits + Streetwise (diff 5): find a nearby abandoned urban hideout, more successes means more secluded. (W20 p. 175)'),
  ('10000000-0000-4000-8000-000000000205', NULL, 'Blissful Ignorance', 2, ARRAY['ragabash','bone_gnawers','silent_striders']::text[], 'stamina', 'stealth', 5, 0, 0, 0, 'Stamina + Stealth (diff 5): each success cancels one success on searchers'' Perception + Alertness; one success hides you from non-searchers. (W20 p. 161)'),
  ('17534b7a-66e4-5b54-93c5-f1a910254e87', NULL, 'Burrow', 2, ARRAY['metis']::text[], 'strength', 'athletics', 6, 0, 0, 0, 'Strength + Athletics: tunnel through earth (needs claws) at 1 yard/turn per success; difficulty rises with material hardness. (W20 p. 156)'),
  ('10000000-0000-4000-8000-000000000208', NULL, 'Call of the Wyrm', 2, ARRAY['galliard']::text[], 'manipulation', 'performance', 7, 0, 0, 0, 'Resisted Manipulation + Performance vs the Wyrm creature''s Willpower (both diff 7); if it loses, it must come to you. (W20 p. 169)'),
  ('2b033b42-99e5-5dc6-b993-a24a47e682c2', NULL, 'Call to Duty', 2, ARRAY['philodox']::text[], 'charisma', 'leadership', 6, 0, 0, 0, 'Summon a named spirit with Charisma + Leadership, or spend 2 Gnosis (no roll) to call all Gaian spirits within 1 mile. (W20 p. 166)'),
  ('10000000-0000-4000-8000-000000000126', NULL, 'Calm', 2, ARRAY['children_of_gaia']::text[], 'charisma', 'empathy', 6, 0, 1, 0, 'Spend 1 Gnosis; Charisma + Empathy vs target''s Willpower: removes 1 target Rage per success; 3 successes end frenzy in Rage-less creatures. (W20 p. 177)'),
  ('10000000-0000-4000-8000-000000000217', NULL, 'Clap of Thunder', 2, ARRAY['shadow_lords']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis (Homid/Glabro/Crinos): all within 20 ft roll Willpower (diff 8 foes, 4 packmates) or are stunned for 1 turn. (W20 p. 189)'),
  ('e71f98c2-ca7e-5956-b2ae-cd1c2156663b', NULL, 'Claws of Frozen Death', 2, ARRAY['wendigo']::text[], 'wits', 'survival', 7, 0, 1, 0, 'Works exactly as Fangs of the North. (W20 p. 200)'),
  ('b8ed2f73-0fb5-5e64-8747-23f868ea7c1e', NULL, 'Coils of the Serpent', 2, ARRAY['uktena']::text[], 'dexterity', 'occult', 7, 0, 0, 0, 'Dexterity + Occult (diff 7): one 30-ft binding coil/success within 100 ft, aimed by Dexterity + Brawl; escape: Strength (diff 7) over coils. (W20 p. 197)'),
  ('425d443f-3d19-575c-abb2-de2849e3042e', NULL, 'Cold Voice of Reason', 2, ARRAY['shadow_lords']::text[], 'manipulation', 'subterfuge', 8, 0, 1, 0, 'Spend 1 Gnosis; Manipulation + Subterfuge (diff 8): attacker is held back one round per success until someone is attacked. (W20 p. 189)'),
  ('10000000-0000-4000-8000-000000000206', NULL, 'Command Spirit', 2, ARRAY['theurge']::text[], 'charisma', 'leadership', 6, 0, 0, 1, 'Spend 1 Willpower; Charisma + Leadership vs spirit Gnosis: it obeys; each further order costs 1 Willpower; cannot evict it from its anchor. (W20 p. 164)'),
  ('e5d9beab-6046-5507-b4dc-7ac4a6e4273a', NULL, 'Command the Gathering', 2, ARRAY['philodox','galliard']::text[], 'appearance', 'leadership', 6, 0, 0, 1, 'Spend 1 Willpower; Appearance + Leadership: listeners go silent; anyone who wants to interrupt or leave must spend 2 Willpower. (W20 p. 167)'),
  ('6ff1ac3f-387a-5392-a121-b42284f5e9f8', NULL, 'Cornered Rat''s Ferocity', 2, ARRAY['bone_gnawers']::text[], 'rage', NULL, 8, 1, 0, 0, 'Spend 1 Rage; Rage roll (diff 8): +1 Brawl die per success for the combat, but triggers an unavoidable berserk frenzy. (W20 p. 175)'),
  ('10000000-0000-4000-8000-000000000211', NULL, 'Curse of Aeolus', 2, ARRAY['black_furies']::text[], 'gnosis', NULL, 6, 0, 0, 0, 'Gnosis roll (diff 4 near water to 9 in desert): city-block fog; others halve Perception pools and lose 1 die on Willpower rolls. (W20 p. 173)'),
  ('10000000-0000-4000-8000-000000000203', NULL, 'Curse of Hatred', 2, ARRAY['metis']::text[], 'manipulation', 'expression', 6, 0, 1, 0, 'Spend 1 Gnosis; Manipulation + Expression vs target''s Willpower: target loses 2 Willpower and 2 Rage; once per scene per target. (W20 p. 156)'),
  ('10000000-0000-4000-8000-000000000221', NULL, 'Cutting Wind', 2, ARRAY['wendigo']::text[], 'dexterity', 'occult', 6, 0, 0, 1, 'Spend 1 Willpower; Dexterity + Occult aims: victims lose 2 dice on all pools for 2 turns, may be shoved; 20 yd range, lasts successes turns. (W20 p. 200)'),
  ('10000000-0000-4000-8000-000000000215', NULL, 'Cybersenses', 2, ARRAY['glass_walkers']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis per sense to swap it for a machine sense (radar, infrared, UV and similar) for the scene. (W20 p. 183)'),
  ('a3bee775-768d-5bf0-8ab6-72c325c384d2', NULL, 'Distractions', 2, ARRAY['galliard']::text[], 'wits', 'performance', 6, 0, 0, 0, 'Wits + Performance vs target''s Willpower: each success removes 1 die from the target''s pools for 3 turns. (W20 p. 169)'),
  ('9b929efc-8ba4-5644-a8e2-6bf6cf706e03', NULL, 'Dreamspeak', 2, ARRAY['galliard']::text[], 'wits', 'empathy', 8, 0, 0, 0, 'Wits + Empathy (diff 8): enter and influence a known target''s dream from any distance; being woken mid-dream costs 1 Gnosis. (W20 p. 169)'),
  ('918baa59-661c-5c90-87fc-eb344f1f85c4', NULL, 'Empathy', 2, ARRAY['silver_fangs']::text[], 'intelligence', 'empathy', 4, 0, 1, 0, 'Spend 1 Gnosis; Intelligence + Empathy (diff 4): learn a group''s general feelings and expectations, in more detail with more successes. (W20 p. 193)'),
  ('5cd34acd-d67e-58de-9e7e-2c8cfc9e372e', NULL, 'Eye of the Eagle', 2, ARRAY['lupus']::text[], 'perception', 'alertness', 7, 0, 0, 0, 'Perception + Alertness (diff 7): each success extends clear line-of-sight vision by one mile. (W20 p. 159)'),
  ('88ff2a90-718b-59eb-9eab-c5dac4e619dc', NULL, 'Fangs of the North', 2, ARRAY['get_of_fenris']::text[], 'wits', 'survival', 7, 0, 1, 0, 'Spend 1 Gnosis; Wits + Survival (diff 7): icy claws/fangs for the scene inflict -1 penalty, block fast healing; not in Homid. (W20 p. 180)'),
  ('aa0ef3ca-a9fb-5827-8021-b4a45fd471a3', NULL, 'Feed the Pack', 2, ARRAY['kucha_ekundu']::text[], 'gnosis', NULL, 6, 0, 0, 0, 'Gnosis roll before eating (diff 6 packmates, 7 Kinfolk): each success lets your meal feed one additional being. (W20 p. 186)'),
  ('da36dd77-8077-5476-8e30-9a58b1e43e26', NULL, 'Fetish Fetch', 2, ARRAY['uktena']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis to set a hidden cache, then 1 Gnosis per summon or return of any or all fetishes at any distance; one cache at a time. (W20 p. 197)'),
  ('65cf6e74-13a4-5620-b61e-68a807ddf4e1', NULL, 'Flame Dance', 2, ARRAY['fianna']::text[], NULL, NULL, 6, 1, 0, 0, 'Spend 1 Rage reflexively: dodge one attack at full dice pool regardless of other actions, or add 3 dice to a normal dodge. (W20 p. 179)'),
  ('12923e14-acfd-54b7-96d9-8c693973471d', NULL, 'Form Mastery', 2, ARRAY['metis','black_furies','fianna']::text[], NULL, NULL, 6, 0, 0, 0, 'Permanent: all shapeshifting difficulties drop by 1; partial transformations need no Willpower and use difficulty 7. (W20 p. 156)'),
  ('e4b485ff-ef58-50fe-9f26-da25e177d3bb', NULL, 'Fu Xi''s Honor', 2, ARRAY['boli_zousizhe']::text[], NULL, NULL, 6, 1, 0, 0, 'Spend 1 Rage when a helpless kin or packmate is threatened: add dice equal to permanent Honor to every Physical Attribute for the scene. (W20 p. 183)'),
  ('10000000-0000-4000-8000-000000000213', NULL, 'Glib Tongue', 2, ARRAY['fianna']::text[], 'wits', 'expression', 6, 0, 1, 0, 'Spend 1 Gnosis; Wits + Expression (diff listener''s Wits + Alertness): target fully agrees with you 1 turn per success. (W20 p. 179)'),
  ('22ee7b02-607b-589f-92e3-6687e687f641', NULL, 'Grandmother''s Touch', 2, ARRAY['children_of_gaia']::text[], 'intelligence', 'empathy', 6, 0, 1, 0, 'Works as Mother''s Touch but can also heal the user; requires Mother''s Touch. (W20 p. 177)'),
  ('a96d8659-11c1-5de7-8e3a-07d5e06f9581', NULL, 'Guise of the Hound', 2, ARRAY['bone_gnawers']::text[], 'manipulation', 'subterfuge', 7, 0, 0, 0, 'Manipulation + Subterfuge (diff 7): Lupus form passes for a big dog, lasting 1 scene per success. (W20 p. 175)'),
  ('10000000-0000-4000-8000-000000000214', NULL, 'Halt the Coward''s Flight', 2, ARRAY['get_of_fenris']::text[], 'charisma', 'intimidation', 6, 0, 0, 0, 'One turn of focus; Charisma + Intimidation vs target''s Willpower: a fleeing target moves at half speed for the scene. (W20 p. 180)'),
  ('8a2fcbd9-1300-503f-82bc-aea5f09ddbf4', NULL, 'Hand Blade', 2, ARRAY['silver_fangs']::text[], 'dexterity', 'melee', 6, 1, 0, 0, 'Spend 1 Rage: arm becomes a blade for the scene, attacking with Dexterity + Melee (diff 6) for Strength + 2 aggravated damage. (W20 p. 193)'),
  ('70cc3b00-8c63-51d8-8266-3ff314014005', NULL, 'Hands Full of Thunder', 2, ARRAY['glass_walkers']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis: guns she fires never run dry for the scene (if loaded to begin with); automatic fire still limited to avoid jams. (W20 p. 184)'),
  ('10000000-0000-4000-8000-000000000312', NULL, 'Howl of the Banshee', 2, ARRAY['fianna']::text[], 'charisma', 'intimidation', 6, 0, 1, 0, 'Spend 1 Gnosis; Charisma + Intimidation: listeners roll Willpower (diff 8, or 6 for Fianna allies) or flee one turn per success. (W20 p. 179)'),
  ('81e38904-7b74-5284-8bed-391706de1ab8', NULL, 'Howl of the Unseen', 2, ARRAY['fianna']::text[], 'gnosis', NULL, 6, 0, 0, 0, 'Roll Gnosis vs local Gauntlet: for 1 turn per success your voice is audible on both sides of the Gauntlet. (W20 p. 179)'),
  ('5b531903-a982-5c7e-be33-13517f1c655a', NULL, 'Howls in the Night', 2, ARRAY['galliard','red_talons','shadow_lords']::text[], 'charisma', 'primal_urge', 7, 0, 1, 0, 'Spend 1 Gnosis; Charisma + Primal-Urge (diff 7): Wyrm creatures hearing it wake and cannot sleep for successes x 3 hours. (W20 p. 169)'),
  ('9bc3cf6b-42a7-513a-af63-544e1a45f80f', NULL, 'Inner Light', 2, ARRAY['stargazers']::text[], NULL, NULL, 6, 0, 0, 0, 'Passive: you count as using a mirror whenever you step sideways into the Umbra. (W20 p. 195)'),
  ('10000000-0000-4000-8000-000000000140', NULL, 'Inner Strength', 2, ARRAY['stargazers']::text[], 'wits', 'enigmas', 8, 0, 0, 0, 'Concentrate 5 minutes; Wits + Enigmas (diff 8): each success turns 1 Rage into 1 Willpower. (W20 p. 195)'),
  ('10000000-0000-4000-8000-000000000201', NULL, 'Jam Technology', 2, ARRAY['homid','glass_walkers']::text[], 'manipulation', 'crafts', 6, 0, 1, 0, 'Spend 1 Gnosis; Manipulation + Crafts: shuts down one device class within 50 ft for 2 turns per success. (W20 p. 153)'),
  ('330bdf72-6532-5d2a-ac47-58e821aa2bbd', NULL, 'Kali''s Tongue', 2, ARRAY['black_furies']::text[], 'manipulation', 'medicine', 6, 1, 0, 0, 'Spend 1 Rage; Manipulation + Medicine: each success blocks target from healing by any means for one turn. (W20 p. 173)'),
  ('10000000-0000-4000-8000-000000000207', NULL, 'King of the Beasts', 2, ARRAY['philodox']::text[], 'charisma', 'animal_ken', 7, 0, 0, 0, 'Charisma + Animal Ken (diff 7) on one animal within 100 ft: it obeys unconditionally until released; only one animal at a time. (W20 p. 167)'),
  ('eaecc0f1-b06b-5076-8be4-431ad684c154', NULL, 'Kneel', 2, ARRAY['black_furies']::text[], 'manipulation', 'intimidation', 6, 0, 0, 0, 'Manipulation + Intimidation vs target Willpower: target kneels 1 turn per success unless a supernatural spends Gnosis or similar. (W20 p. 173)'),
  ('10000000-0000-4000-8000-000000000212', NULL, 'Luna''s Armor', 2, ARRAY['children_of_gaia','shadow_lords','silver_fangs']::text[], 'stamina', 'survival', 6, 0, 1, 0, 'One turn of focus, spend 1 Gnosis; Stamina + Survival (diff 6): each success adds a soak die for the scene, usable against silver. (W20 p. 177)'),
  ('b79e909f-5fa1-5b5b-b730-b247e910aefa', NULL, 'Mark of the Wolf', 2, ARRAY['homid']::text[], 'manipulation', 'primal_urge', 7, 0, 0, 0, 'Manipulation + Primal-Urge (diff 7) on someone met this scene: target suffers your Curse at your Rage rating, 1 day per success. (W20 p. 154)'),
  ('e8bce6d3-c434-5048-a777-5f9b6dd26321', NULL, 'Messenger''s Fortitude', 2, ARRAY['silent_striders']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis, no roll: run at full speed for three days without rest or supplies, then sleep a day; extra runners cost 1 Gnosis each. (W20 p. 192)'),
  ('10000000-0000-4000-8000-000000000204', NULL, 'Name the Spirit', 2, ARRAY['lupus','theurge']::text[], 'perception', 'occult', 8, 0, 0, 1, 'Spend 1 Willpower; Perception + Occult (diff 8): learn a spirit''s type and approximate Rage, Gnosis and Willpower. (W20 p. 159)'),
  ('597f57c6-ef41-5afc-97e6-0369a80f9c62', NULL, 'Odious Aroma', 2, ARRAY['bone_gnawers']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis: everyone within 20 ft who can smell, except you and your pack, gets -2 dice on all pools for the scene. (W20 p. 175)'),
  ('0e7e8d67-2bfb-5afc-baa2-475b2d7d0a38', NULL, 'Para Bellum', 2, ARRAY['children_of_gaia']::text[], NULL, NULL, 6, 1, 0, 0, 'Spend 1 Rage when a foe starts a fight: +1 Strength and Dexterity this scene vs the first attacker or anyone who hurt a packmate. (W20 p. 177)'),
  ('82ade59e-904b-5ce2-a90b-e2f02b25d2dc', NULL, 'Power Surge', 2, ARRAY['glass_walkers']::text[], 'wits', 'science', 7, 0, 1, 0, 'Spend 1 Gnosis; Wits + Science (diff 7): blackout whose size scales with successes (1 = a room, 5 = a neighborhood). (W20 p. 184)'),
  ('20e66493-d350-5399-8584-f3119bb2fdde', NULL, 'Pulse of the Prey', 2, ARRAY['ragabash','black_furies','red_talons']::text[], 'perception', 'enigmas', 6, 0, 0, 0, 'Automatically track any named quarry at travel speed; only if it hides roll Perception + Enigmas, with a spirit''s Gnosis as difficulty. (W20 p. 161)'),
  ('4c94216b-5d9d-5dae-97ac-91604fab96f6', NULL, 'Resist Temptation', 2, ARRAY['stargazers']::text[], 'wits', 'rituals', 6, 0, 1, 0, 'Spend 1 Gnosis; Wits + Rituals: each success adds +1 difficulty to supernatural coercion of you this scene; mundane coercion fails. (W20 p. 195)'),
  ('6612ebb4-a30e-5235-a8ac-400d88264dc5', NULL, 'Salmon Swim', 2, ARRAY['wendigo']::text[], 'dexterity', 'athletics', 7, 0, 1, 0, 'Spend 1 Gnosis; Dexterity + Athletics (diff 7): move freely on/under natural fresh water, plus Hare''s Leap between waters; scene per success. (W20 p. 200)'),
  ('2f7f0ea0-d98d-52c0-997e-34960114be47', NULL, 'Scent of Sight', 2, ARRAY['lupus']::text[], NULL, NULL, 6, 0, 0, 0, 'No activation roll: smell stands in for sight (no color or print); scent-masking may call for Perception + Primal-Urge. (W20 p. 159)'),
  ('10000000-0000-4000-8000-000000000210', NULL, 'Sense Silver', 2, ARRAY['metis','ahroun','silver_fangs']::text[], 'perception', 'primal_urge', 7, 0, 0, 0, 'Perception + Primal-Urge (diff 7): detect silver within 100 yards; 3 successes pinpoint it. (W20 p. 156)'),
  ('10000000-0000-4000-8000-000000000220', NULL, 'Shadows at Dawn', 2, ARRAY['uktena']::text[], 'wits', 'subterfuge', 6, 0, 0, 0, 'After sharing information, Wits + Subterfuge: target forgets it at the next sunrise. (W20 p. 198)'),
  ('81c374e3-87db-521a-a13c-436809759fee', NULL, 'Shadows of the Impergium', 2, ARRAY['red_talons']::text[], NULL, NULL, 6, 0, 0, 0, 'Permanent passive: Hispo form causes Delirium (viewers +2 Willpower); Crinos viewers count as 5 Willpower lower (min 1). (W20 p. 186)'),
  ('00fad055-e9d3-5076-a44e-eea6d7edbc91', NULL, 'Shield of Rage', 2, ARRAY['ahroun']::text[], NULL, NULL, 6, 0, 0, 1, 'Spend 1 Willpower: for the scene, spirits'' Rage counts as 2 lower when rolling damage against you. (W20 p. 171)'),
  ('d5ed0195-b1fa-507f-9f75-b22436a455ef', NULL, 'Sight From Beyond', 2, ARRAY['theurge']::text[], 'wits', 'occult', 7, 0, 0, 0, 'Storyteller-driven prophetic visions; a player may roll Wits + Occult (diff 7) to decode a confusing one. (W20 p. 164)'),
  ('f1bd2d38-a213-5193-84e0-f9061836037d', NULL, 'Snarl of the Predator', 2, ARRAY['get_of_fenris']::text[], 'charisma', 'intimidation', 6, 0, 0, 0, 'Takes a full turn; Charisma + Intimidation: each success cuts 1 die from the opponent''s pools for 3 turns. (W20 p. 180)'),
  ('a538648e-429c-55c7-b85a-ebad54bb5280', NULL, 'Song of the Earth Mother', 2, ARRAY['shadow_lords']::text[], 'perception', 'occult', 7, 0, 2, 0, 'After 10 minutes communing, spend 2 Gnosis; Perception + Occult (diff 7): sense supernaturals within 100 yds per success, and Wyrm taint. (W20 p. 190)'),
  ('721a3e02-30ab-5e9b-a5ca-59770e2ecf30', NULL, 'Speak with Wind Spirits', 2, ARRAY['wendigo']::text[], 'manipulation', 'expression', 8, 0, 0, 0, 'Manipulation + Expression (diff 8): ask local wind-spirits one question about the area; successes set accuracy; fails indoors. (W20 p. 200)'),
  ('49a5e436-aa34-5b88-8f99-16f112e8b53d', NULL, 'Speech of the World', 2, ARRAY['homid','silent_striders']::text[], 'intelligence', 'academics', 7, 0, 0, 0, 'Intelligence + Academics (diff 7): speak and understand any human tongue for a scene, with an accent; grants no literacy. (W20 p. 154)'),
  ('2aab77bc-1847-50f1-9aa9-182cd098fdfc', NULL, 'Spider''s Song', 2, ARRAY['ragabash']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis, no roll: eavesdrop on a known phone or text conversation while touching the line or watching the phone user. (W20 p. 161)'),
  ('99554c8d-7e01-50c8-9941-afee01d91e45', NULL, 'Spirit of the Bird', 2, ARRAY['uktena']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis: fly or hover at 20 mph for 1 hour, with all combat maneuver difficulties +1. (W20 p. 198)'),
  ('89e72a63-aea3-5f27-9375-2f1de88a2105', NULL, 'Spirit of the Fish', 2, ARRAY['uktena']::text[], 'stamina', 'animal_ken', 7, 0, 1, 0, 'Spend 1 Gnosis; Stamina + Animal Ken (diff 7): breathe water and swim at Hispo running speed for 1 hour per success. (W20 p. 198)'),
  ('10000000-0000-4000-8000-000000000209', NULL, 'Spirit of the Fray', 2, ARRAY['ahroun']::text[], NULL, NULL, 6, 0, 0, 0, 'Permanent, no roll: +10 to initiative; optionally spend 1 Gnosis for another +10, which bars Rage-bought extra actions that turn. (W20 p. 171)'),
  ('10000000-0000-4000-8000-000000000202', NULL, 'Staredown', 2, ARRAY['homid']::text[], 'charisma', 'intimidation', 6, 0, 0, 0, 'Charisma + Intimidation (diff 5 + Rank): target flees 1 turn/success (scene at 5+); Willpower resists; Rage-users merely can''t attack. (W20 p. 154)'),
  ('e44fbb5f-7149-5c94-93eb-87dd10befe95', NULL, 'Steel Fur', 2, ARRAY['glass_walkers']::text[], 'stamina', 'science', 7, 0, 0, 1, 'Spend 1 Willpower; Stamina + Science (diff 7): +1 soak die per success for the scene, but +1 difficulty on Dexterity and most Social rolls. (W20 p. 184)'),
  ('d3cb174b-a972-51e6-85bd-1f24e5f64a8c', NULL, 'Storm Winds Slash', 2, ARRAY['hakken']::text[], 'dexterity', 'melee', 7, 0, 1, 0, 'Spend 1 Gnosis; Dexterity + Melee (diff 7): a blade strike reaches 50 yards, lethal damage, target may dodge. (W20 p. 189)'),
  ('10000000-0000-4000-8000-000000000306', NULL, 'Strength of Purpose', 2, ARRAY['philodox']::text[], 'stamina', 'rituals', 7, 0, 0, 0, 'Once per scene, Stamina + Rituals (diff 7): regain 1 Willpower per 2 successes, up to maximum. (W20 p. 167)'),
  ('10000000-0000-4000-8000-000000000219', NULL, 'Surface Attunement', 2, ARRAY['stargazers']::text[], 'dexterity', 'athletics', 6, 0, 0, 0, 'Concentrate a turn; Dexterity + Athletics (diff 6): cross water, mud, snow and quicksand at normal speed leaving no tracks for the scene. (W20 p. 195)'),
  ('13247afc-bbe6-5ca6-b3ee-a12b594bb718', NULL, 'Taking the Forgotten', 2, ARRAY['ragabash']::text[], 'wits', 'larceny', 6, 0, 0, 0, 'After a successful theft, 3 successes on Wits + Larceny (diff victim''s Intelligence + Streetwise) make the victim forget the item. (W20 p. 162)'),
  ('af87964f-f67e-5a6c-b150-9f5fd9ae1a15', NULL, 'Tread Sebek''s Back', 2, ARRAY['silent_striders']::text[], 'dexterity', 'survival', 7, 0, 1, 0, 'Spend 1 Gnosis; Dexterity + Survival (diff 7): walk across liquids like solid ground for 1 hour per success, with no foot protection. (W20 p. 192)'),
  ('59fd2ef5-4c71-5a04-8da3-f81ada5c6c7e', NULL, 'Troll Skin', 2, ARRAY['get_of_fenris']::text[], 'stamina', 'primal_urge', 5, 0, 1, 0, 'Spend 1 Gnosis; Stamina + Primal-Urge (diff 5): +1 soak die per success for the scene (not vs silver); +1 diff on non-Intimidation Social. (W20 p. 181)'),
  ('3b1f5ae4-ba2d-5aa4-9ce3-73de012c3aef', NULL, 'True Fear', 2, ARRAY['ahroun','wendigo']::text[], 'strength', 'intimidation', 6, 0, 0, 0, 'Strength + Intimidation: one foe cannot attack for 1 turn per success but can defend and act otherwise. (W20 p. 171)'),
  ('3a009a7f-f1c4-55e3-bc9c-dd1160478f1b', NULL, 'Unicorn''s Arsenal', 2, ARRAY['children_of_gaia']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis: wounds from her claws and fangs impose -2 dice on the victim''s attack rolls until healed. (W20 p. 177)'),
  ('cab0a185-4dcc-5f5e-9252-04cd8bd0267e', NULL, 'Unity of the Pack', 2, ARRAY['silver_fangs']::text[], NULL, NULL, 6, 0, 0, 0, 'Passive: while you are present, you and packmates get +1 die on Pack Tactics rolls; no benefit if alone. (W20 p. 194)'),
  ('64e3b49f-a418-51a7-9970-14d8b7b32ddc', NULL, 'Wuxing', 2, ARRAY['stargazers']::text[], 'manipulation', 'enigmas', 7, 0, 0, 0, 'Manipulation + Enigmas (diff 7): converts 1 sq ft per success between Chinese elements, keeping shape, for turns equal to her Gnosis. (W20 p. 195)'),
  ('10000000-0000-4000-8000-000000000317', NULL, 'Adaptation', 3, ARRAY['silent_striders']::text[], 'stamina', 'survival', 7, 0, 1, 0, 'Spend 1 Gnosis; Stamina + Survival (diff 7): immune to poison, disease and hostile environments for 1 hour per success. (W20 p. 192)'),
  ('a9934d0e-fb5c-5b42-8c8d-eb1c35e119c6', NULL, 'Banish Totem', 3, ARRAY['uktena']::text[], 'gnosis', NULL, 6, 0, 1, 1, 'Full-turn focus, spend 1 Gnosis and 1 Willpower; Gnosis roll: targeted pack loses totem Traits and pack tactics for the scene. (W20 p. 198)'),
  ('706d0d7d-cd80-53a4-8504-4853ab52d44f', NULL, 'Blood of the North', 3, ARRAY['wendigo']::text[], NULL, NULL, 6, 0, 0, 0, 'Permanent, no roll: ignore cold penalties, +5 soak dice versus cold attacks, and -2 difficulty on Survival rolls in cold places. (W20 p. 201)'),
  ('10000000-0000-4000-8000-000000000321', NULL, 'Bloody Feast', 3, ARRAY['wendigo']::text[], 'gnosis', NULL, 6, 0, 0, 0, 'After a damaging bite, roll Gnosis: +1 Strength per 2 levels dealt (max +5) for 2 turns per success, then a frenzy roll. (W20 p. 201)'),
  ('470e44c9-b625-5d80-a5c2-d6269a031939', NULL, 'Burning Blade', 3, ARRAY['silver_fangs']::text[], 'gnosis', NULL, 7, 0, 0, 0, 'After a turn of focus, roll Gnosis (diff 7): your weapon deals +2 aggravated fire dice and ignites flammables for successes-many turns. (W20 p. 194)'),
  ('10000000-0000-4000-8000-000000000310', NULL, 'Call the Rust', 3, ARRAY['bone_gnawers']::text[], 'wits', 'crafts', 6, 0, 1, 0, 'Spend 1 Gnosis; Wits + Crafts: nearby metal corrodes and fails; difficulty scales with how much metal. (W20 p. 175)'),
  ('31c20604-3076-5bd2-a954-2ffa5fae409f', NULL, 'Calm the Savage Beast', 3, ARRAY['homid','children_of_gaia']::text[], 'manipulation', 'primal_urge', 8, 0, 0, 1, 'Spend 1 Willpower; Manipulation + Primal-Urge (diff 8): ends a Garou''s frenzy within 30 ft; +1 Willpower covers non-Garou. (W20 p. 154)'),
  ('10000000-0000-4000-8000-000000000303', NULL, 'Catfeet', 3, ARRAY['lupus']::text[], NULL, NULL, 6, 0, 0, 0, 'Passive: no damage from falls under 100 ft, perfect balance, and -2 difficulty on body slams and grapples. (W20 p. 159)'),
  ('8d593a3c-dc87-5b96-be8a-b17488cd25de', NULL, 'Chains of Mist', 3, ARRAY['uktena']::text[], 'dexterity', 'enigmas', 7, 0, 1, 0, 'Concentrate a turn, spend 1 Gnosis; Dexterity + Enigmas (diff 7): 1 spirit/success within 200 ft gets Rage, Gnosis, Willpower -1 this scene. (W20 p. 198)'),
  ('48de5266-bb98-5e1b-9664-fe91ba6e1fb7', NULL, 'Chameleon', 3, ARRAY['metis']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis; observers need Perception vs your Wits + Stealth to see you, and difficulty drops 3 after you attack; sight only. (W20 p. 156)'),
  ('c5b09421-195b-53fa-be57-b4f5856478bb', NULL, 'Clarity', 3, ARRAY['stargazers']::text[], 'perception', 'enigmas', 7, 0, 0, 0, 'Perception + Enigmas (diff 7): negates fog and darkness penalties; vs. illusions, must match or beat the creator''s successes. (W20 p. 196)'),
  ('10000000-0000-4000-8000-000000000308', NULL, 'Combat Healing', 3, ARRAY['ahroun']::text[], NULL, NULL, 6, 0, 0, 0, 'Permanent; no roll. Regenerates 1 non-aggravated health level each round in combat with no pause or Stamina roll. (W20 p. 171)'),
  ('10000000-0000-4000-8000-000000000314', NULL, 'Control Complex Machine', 3, ARRAY['glass_walkers']::text[], 'manipulation', 'science', 6, 0, 0, 1, 'Spend 1 Willpower; Manipulation + Science or Computer: command an electronic device''s spirit for a scene (laptop is diff 8). (W20 p. 184)'),
  ('10000000-0000-4000-8000-000000000309', NULL, 'Coup de Grace', 3, ARRAY['black_furies']::text[], 'perception', 'brawl', 6, 0, 0, 1, 'Spend 1 Willpower; Perception + Brawl: on success, your next successful attack rolls double damage dice. (W20 p. 173)'),
  ('02aa73f6-8264-5932-a1d3-3617591888af', NULL, 'Cowing the Bullet', 3, ARRAY['homid']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis: +2 soak dice vs. all non-silver man-made weapons for the scene. (W20 p. 154)'),
  ('df234704-b97c-509d-b1d1-f45519671330', NULL, 'Dark of Night', 3, ARRAY['hakken']::text[], 'manipulation', 'subterfuge', 6, 0, 1, 0, 'Spill ink and spend 1 Gnosis; Manipulation + Subterfuge resisted by target''s Gnosis: blinds the victim 1 hour per success. (W20 p. 189)'),
  ('10000000-0000-4000-8000-000000000311', NULL, 'Dazzle', 3, ARRAY['children_of_gaia']::text[], 'charisma', 'empathy', 6, 0, 0, 0, 'Charisma + Empathy: target stands entranced for the scene unless attacked; one attempt per target per scene. (W20 p. 178)'),
  ('b13cd448-eaff-5491-86bb-3896651ec718', NULL, 'Direct the Storm', 3, ARRAY['shadow_lords']::text[], 'willpower', NULL, 6, 0, 1, 0, 'Spend 1 Gnosis; Willpower vs target Rage: steer a frenzying werewolf at chosen victims 2 turns/success; Thralls need your Rage roll (7). (W20 p. 190)'),
  ('10000000-0000-4000-8000-000000000301', NULL, 'Disquiet', 3, ARRAY['homid']::text[], 'manipulation', 'empathy', 6, 0, 0, 0, 'Manipulation + Empathy vs target''s Willpower: target can''t regain Rage this scene, extended-action difficulties +1, and is apathetic. (W20 p. 154)'),
  ('0e66e47a-25ab-523a-a50a-50660540b1ff', NULL, 'Electroshock', 3, ARRAY['glass_walkers']::text[], NULL, NULL, 6, 1, 0, 0, 'Spend Rage (min 1, max half permanent per turn): each point deals 2 aggravated, splittable among touched or conductive-linked foes. (W20 p. 184)'),
  ('b4d6dec3-858b-57ce-a575-20abe6dc4cd6', NULL, 'Elemental Favor', 3, ARRAY['glass_walkers','red_talons']::text[], 'charisma', 'subterfuge', 7, 0, 0, 0, 'Charisma + Subterfuge (diff 7): an urban elemental performs a favor with its physical form; Storyteller sets the exact result. (W20 p. 184)'),
  ('c451c5c7-76d9-526c-95c9-aa942c12dd26', NULL, 'Exorcism', 3, ARRAY['theurge']::text[], 'manipulation', 'intimidation', 6, 0, 0, 0, 'Concentrate 3 turns; if unwilling, Manipulation + Intimidation vs spirit''s Willpower (beat binder if bound); on fomori deals 10 aggravated. (W20 p. 165)'),
  ('9d21a972-43e3-5c39-b291-12f9f321bed8', NULL, 'Eye of the Cobra', 3, ARRAY['galliard']::text[], 'appearance', 'enigmas', 6, 0, 0, 0, 'Appearance + Enigmas (diff = target''s Willpower): 3 successes draw the target to her; fewer only start them moving. (W20 p. 169)'),
  ('10000000-0000-4000-8000-000000000302', NULL, 'Eyes of the Cat', 3, ARRAY['metis']::text[], NULL, NULL, 6, 0, 0, 0, 'Free and roll-free, usable at will: darkness imposes no penalties on you. (W20 p. 157)'),
  ('a730d281-2a63-5ac2-b1ed-33d5af70eebb', NULL, 'Faerie Kin', 3, ARRAY['fianna']::text[], 'manipulation', 'occult', 8, 0, 1, 0, 'Spend 1+ Gnosis; Manipulation + Occult (diff 8): nearby fae answer, more Gnosis means stronger ones, more successes means more of them. (W20 p. 179)'),
  ('aa20e68e-bc07-5206-ad70-bec2e9541dce', NULL, 'Fair Fortune', 3, ARRAY['fianna']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis to reroll one failed or botched roll, keeping the new result; once per scene. (W20 p. 179)'),
  ('64947f5f-fdf7-5a52-b994-cd126971b81a', NULL, 'Gift of the Skunk', 3, ARRAY['bone_gnawers']::text[], 'dexterity', 'primal_urge', 7, 0, 0, 0, 'Dexterity + Primal-Urge (diff 7, 10 ft): target retches a turn unless paying 1 Willpower, then -1 die per 2 successes; water negates. (W20 p. 175)'),
  ('ad561a38-3df3-5b70-8ef4-2604e88d6d04', NULL, 'Gift of the Termite', 3, ARRAY['bone_gnawers']::text[], 'intelligence', 'crafts', 7, 0, 1, 0, 'Spend 1 Gnosis; Intelligence + Crafts (diff 7): rot wood and paper; 1 success a ream, 3 a wall, 5 a small roof. (W20 p. 175)'),
  ('b4266201-a9bb-5ec1-8292-f554f4b6e4d2', NULL, 'Great Leap', 3, ARRAY['silent_striders']::text[], 'strength', 'athletics', 6, 0, 0, 1, 'Spend 1 Willpower; Strength + Athletics: each success covers a 100-foot jump. (W20 p. 192)'),
  ('10000000-0000-4000-8000-000000000304', NULL, 'Gremlins', 3, ARRAY['ragabash']::text[], 'manipulation', 'intimidation', 6, 0, 0, 0, 'Touch; Manipulation + Intimidation: damages device per success, 3 breaks it. Diff: computer 4, phone 6, car 7, gun 8, knife 9. (W20 p. 162)'),
  ('8a9dd6a1-dc8a-5b22-a0c6-70d6c99d9093', NULL, 'Heart Claw', 3, ARRAY['black_furies']::text[], NULL, NULL, 6, 0, 0, 1, 'After a claw hit, spend 1 Willpower: lodged claw deals 1 unsoakable lethal per turn until death or removal (Dex + Medicine 7). (W20 p. 173)'),
  ('446265a9-ff0d-55d7-bb3f-1d4841cf6b2b', NULL, 'Heart of Fury', 3, ARRAY['ahroun']::text[], 'willpower', NULL, 6, 0, 0, 0, 'Willpower roll (diff permanent Rage): each 2 successes give +1 frenzy difficulty for the scene; after, pay 1 Willpower or test frenzy. (W20 p. 171)'),
  ('941519d1-402c-5611-8f78-6e8ae1117a40', NULL, 'Icy Chill of Despair', 3, ARRAY['shadow_lords']::text[], 'manipulation', 'intimidation', 7, 0, 1, 0, 'Spend 1 Gnosis; Manipulation + Intimidation (diff 7): hostile foes must beat you on Willpower (diff 8) or pay 1 Willpower to oppose. (W20 p. 190)'),
  ('8b65a64a-5269-5eae-b561-338c100d38db', NULL, 'Intrusion', 3, ARRAY['glass_walkers']::text[], 'gnosis', NULL, 7, 0, 1, 0, 'Spend 1 Gnosis; Gnosis roll (diff 7): for 1 minute all locks and barriers open for you; mystic seals get 1 auto success per success rolled. (W20 p. 184)'),
  ('10000000-0000-4000-8000-000000000320', NULL, 'Invisibility', 3, ARRAY['uktena']::text[], 'intelligence', 'occult', 6, 0, 1, 0, 'Spend 1 Gnosis; Intelligence + Occult (diff 4/6/9): searchers must beat successes on Perception + Alertness (diff 8); half speed. (W20 p. 198)'),
  ('74543d7a-15ea-5019-ade4-1c82346de3e2', NULL, 'Laugh of the Hyena', 3, ARRAY['bone_gnawers']::text[], NULL, NULL, 6, 0, 0, 0, 'No roll; while laughing aloud, attempts to mentally compel the user get +2 difficulty. (W20 p. 175)'),
  ('5723ad19-4d46-57fd-b846-3d5c6afc4a4f', NULL, 'Ley Lines', 3, ARRAY['fianna']::text[], 'wits', 'occult', 7, 0, 1, 0, 'Spend 1 Gnosis; Wits + Occult (diff 7): trackers must win Perception + Occult (diff 8) or their pursuit botches automatically. (W20 p. 179)'),
  ('42c35ea4-09b5-5030-8247-254249183aa2', NULL, 'Liar''s Craft', 3, ARRAY['ragabash']::text[], 'wits', 'subterfuge', 6, 0, 0, 0, 'Wits + Subterfuge rolled after the lie: 1 success fools one person, 3 fool a crowd. (W20 p. 162)'),
  ('d0dc5ae1-81de-5691-aba2-7e72069daa0a', NULL, 'Lover''s Touch', 3, ARRAY['children_of_gaia']::text[], 'intelligence', 'medicine', 6, 0, 1, 0, 'Spend 1 Gnosis; Intelligence + Medicine, kind touch: each success heals bashing/lethal, restores Willpower/Essence, or delays Derangement. (W20 p. 178)'),
  ('6a02ad9f-cfff-52da-a5fd-c55864504fdc', NULL, 'Mark of the Death-Wolf', 3, ARRAY['silent_striders']::text[], 'wits', 'occult', 7, 0, 1, 0, 'Spend 1 Gnosis and a turn carving a sigil; Wits + Occult (diff 7): draws and haunts with ghosts 1 week per success unless destroyed. (W20 p. 192)'),
  ('7ebf6c07-76f5-5d50-ab47-578739605f6e', NULL, 'Mental Speech', 3, ARRAY['metis','philodox']::text[], 'charisma', 'empathy', 8, 0, 0, 1, 'Spend 1 Willpower; Charisma + Empathy (diff 8): telepathic chat for a scene with a known target, 10 miles range per success. (W20 p. 157)'),
  ('10000000-0000-4000-8000-000000000319', NULL, 'Merciful Blow', 3, ARRAY['stargazers']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis: for the scene your attacks leave no wounds; foes put down regain that damage and stay unconscious through the scene. (W20 p. 196)'),
  ('10000000-0000-4000-8000-000000000313', NULL, 'Might of Thor', 3, ARRAY['get_of_fenris']::text[], 'willpower', NULL, 8, 1, 1, 0, 'Spend 1 Gnosis and 1 Rage; Willpower (diff 8): Strength doubles for 1 turn per success; once per scene. (W20 p. 181)'),
  ('8c997b23-15fc-521d-a923-aecea5a0bc00', NULL, 'Monkey Tail', 3, ARRAY['lupus','ragabash']::text[], 'dexterity', 'athletics', 6, 0, 0, 0, 'Permanent prehensile tail in any tailed form; using it for tasks requires Dexterity + Athletics at a task-dependent difficulty. (W20 p. 159)'),
  ('05e8a51c-30f2-507a-a012-2f7569a752ca', NULL, 'Open Moon Bridge', 3, ARRAY['ragabash']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis to open a moon bridge, even without the caern totem''s consent, spanning up to 1,000 miles. (W20 p. 162)'),
  ('10000000-0000-4000-8000-000000000316', NULL, 'Paralyzing Stare', 3, ARRAY['shadow_lords']::text[], 'charisma', 'intimidation', 6, 0, 1, 0, 'Concentrate a turn, spend 1 Gnosis; Charisma + Intimidation vs target''s Willpower: it freezes 1 turn/success (can defend); needs sight. (W20 p. 190)'),
  ('477ac814-4de6-5309-a73b-8bdfbda041bc', NULL, 'Pathfinder', 3, ARRAY['ragabash']::text[], 'perception', 'survival', 7, 0, 0, 0, 'Perception + Survival (wild) or Streetwise (urban), diff 7: ~10% less travel time per success (max half); trackers get +2 difficulty. (W20 p. 162)'),
  ('27cb9617-133a-5c5e-ac06-a6d099824186', NULL, 'Predator''s Many Eyes', 3, ARRAY['kucha_ekundu']::text[], 'charisma', 'animal_ken', 7, 0, 0, 0, 'Charisma + Animal Ken (diff 7) with a predator in sight: mark it and see through its eyes, as the Territory Gift; other Fera must consent. (W20 p. 186)'),
  ('10000000-0000-4000-8000-000000000305', NULL, 'Pulse of the Invisible', 3, ARRAY['theurge']::text[], 'gnosis', NULL, 6, 0, 0, 0, 'Perceive the Umbra for the scene: automatic if permanent Gnosis meets the Gauntlet, otherwise a Gnosis roll vs the Gauntlet. (W20 p. 165)'),
  ('6eed89b3-79f0-5306-8f9d-e88bf0dc9fce', NULL, 'Redirect Pain', 3, ARRAY['get_of_fenris']::text[], 'manipulation', 'primal_urge', 8, 1, 0, 0, 'Spend 1 Rage; Manipulation + Primal-Urge (diff 8): target suffers the user''s current wound penalties for one scene. (W20 p. 181)'),
  ('10000000-0000-4000-8000-000000000216', NULL, 'Render Down', 3, ARRAY['red_talons']::text[], 'rage', NULL, 7, 0, 0, 0, 'Touch a man-made material; Rage roll (diff 7): each success breaks down 20 lb of it. Natural materials are unaffected. (W20 p. 186)'),
  ('b6b23fad-004e-5bee-93fb-fc1962dc1727', NULL, 'Rending the Craft', 3, ARRAY['uktena']::text[], NULL, NULL, 6, 0, 0, 1, 'After a hit with claws, spend 1 Willpower: end temporary magical effects on the target, leaving permanent or innate ones. (W20 p. 198)'),
  ('77a6e035-5ea9-51ef-99b5-06da065f3445', NULL, 'Reshape Object', 3, ARRAY['homid','bone_gnawers','fianna']::text[], 'manipulation', 'crafts', 6, 0, 1, 0, 'Spend 1 Gnosis; Manipulation + Crafts: remake organic matter into an item, 1 scene/success (5+ permanent); +1 Gnosis: aggravated weapon. (W20 p. 154)'),
  ('f1d7f25d-e6b2-5b0d-a6fe-e4ac3ac65d1f', NULL, 'Scent of the Oathbreaker', 3, ARRAY['philodox']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis to bind a witnessed oath; if broken he knows at once, and scent-tracking the breaker is diff 4 until they meet. (W20 p. 167)'),
  ('bf040cfc-d685-5e05-930d-4315a8b357c6', NULL, 'Scrying', 3, ARRAY['uktena']::text[], 'perception', 'occult', 10, 0, 1, 0, 'Spend 1 Gnosis; Perception + Occult (diff 10, or 8 with the subject''s item): watch a person or place via a reflective surface for the scene. (W20 p. 198)'),
  ('01298df5-0a43-566b-ac7b-9c03e87f2ef6', NULL, 'Sense Balance', 3, ARRAY['philodox','stargazers']::text[], 'perception', 'enigmas', 8, 0, 1, 0, 'Spend 1 Gnosis; Perception + Enigmas (diff 8): read Wyrm, Weaver or Wyld imbalance in an area; requires calm focus. (W20 p. 167)'),
  ('052811f7-0748-5721-afae-69afc7f810a8', NULL, 'Sense the Unnatural', 3, ARRAY['lupus','silent_striders']::text[], 'perception', 'enigmas', 6, 0, 0, 0, 'Perception + Enigmas (diff 6): detects nearby supernatural presences and their rough strength and type; more successes give more detail. (W20 p. 159)'),
  ('2bf58f27-717f-50b6-9986-2821f6c9b4c9', NULL, 'Shadow Cutting', 3, ARRAY['shadow_lords']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis: for the scene, fetish/natural weapons can strike the foe shadow; victim has -2 dodge dice and cannot parry. (W20 p. 190)'),
  ('ef5d0e14-c2f6-569f-af52-0a03f94f1676', NULL, 'Shell', 3, ARRAY['metis']::text[], 'willpower', NULL, 6, 0, 0, 0, 'Willpower vs own Rage: immune to mind magic this scene, but no successes on Empathy, Primal-Urge, Rage rolls and no Rage spending. (W20 p. 157)'),
  ('703929f5-ee17-53bf-9055-e82978686444', NULL, 'Silence the Weaver', 3, ARRAY['lupus']::text[], 'manipulation', 'primal_urge', 6, 1, 0, 0, 'Howl one turn, spend 1 Rage; Manipulation + Primal-Urge: destroys delicate electronics within 20 x successes yards. (W20 p. 160)'),
  ('c567a081-1922-5182-9710-0f99041af97f', NULL, 'Silver Claws', 3, ARRAY['ahroun','silver_fangs']::text[], 'gnosis', NULL, 7, 0, 0, 0, 'Gnosis (diff 7): claws become silver, dealing aggravated damage; each turn +1 Rage and +1 non-combat difficulty; lasts a scene. (W20 p. 171)'),
  ('596dc33b-b5d9-5905-92c7-93ac7e4d2d89', NULL, 'Sky Running', 3, ARRAY['wendigo']::text[], NULL, NULL, 6, 0, 0, 1, 'Concentrate a turn and spend 1 Willpower: run through the air at 50 mph leaving fire; lasts 4 hours, renewable with more Willpower. (W20 p. 201)'),
  ('71cc2a8e-dcc4-52a3-a2bb-bf5062969eae', NULL, 'Song of Heroes', 3, ARRAY['galliard']::text[], 'charisma', 'performance', 8, 0, 2, 0, 'After a long tale, spend 2 Gnosis; Charisma + Performance (diff 8): each 2 successes give listeners +1 to one Ability until sunrise. (W20 p. 170)'),
  ('10000000-0000-4000-8000-000000000307', NULL, 'Song of Rage', 3, ARRAY['galliard']::text[], 'manipulation', 'leadership', 6, 0, 0, 0, 'Manipulation + Leadership vs target''s Willpower: target rages or frenzies for 1 turn per success. (W20 p. 170)'),
  ('fbb2960c-434e-53b2-b01b-8a94221a74f7', NULL, 'Song of the Siren', 3, ARRAY['galliard','fianna']::text[], 'charisma', 'performance', 6, 0, 1, 0, 'Spend 1 Gnosis; Charisma + Performance vs Willpower: non-packmates idle turns equal to successes unless paying 1 Willpower per turn. (W20 p. 170)'),
  ('501f9a06-cce0-5523-9aa5-f4d31794f89f', NULL, 'Spirit Friend', 3, ARRAY['children_of_gaia']::text[], 'charisma', 'empathy', 7, 0, 0, 0, 'Charisma + Empathy (diff 7): +1 die per success on all your pools versus non-Bane spirits, lasting the scene. (W20 p. 178)'),
  ('b36374f6-6476-5236-83fe-885f74c50b3c', NULL, 'Strength of Gaia', 3, ARRAY['lupus']::text[], NULL, NULL, 6, 1, 0, 0, 'Spend 1 Rage: in Lupus form your base Strength bonus is +4 instead of +1 for the scene. (W20 p. 160)'),
  ('9313d863-00e1-52cf-9947-b41fe0ec4844', NULL, 'Talons of the Falcon', 3, ARRAY['silver_fangs']::text[], 'dexterity', 'brawl', 6, 0, 1, 0, 'Spend 1 Gnosis; Dexterity + Brawl attack: deals 3 extra damage levels that cannot be regenerated for the scene. (W20 p. 194)'),
  ('42ed6882-b293-5af4-a737-caae6646cdaa', NULL, 'Territory', 3, ARRAY['red_talons']::text[], 'perception', 'primal_urge', 7, 0, 0, 0, 'Urine-mark up to Gnosis areas; Perception + Primal-Urge (diff 7) senses a marked site remotely; marks last 1 week/dot wild, 1 day/dot urban. (W20 p. 187)'),
  ('f131b4ae-c97d-53e3-8a13-fe94157f4287', NULL, 'Trackless Waste', 3, ARRAY['red_talons']::text[], 'intelligence', 'primal_urge', 6, 0, 1, 0, 'Spend 1 Gnosis; Intelligence + Primal-Urge (diff 6): 2-mile radius/success, humans lost, werewolves may resist via Perception + Primal-Urge. (W20 p. 187)'),
  ('1015a441-4a98-5ac8-b0d3-12ef98c35810', NULL, 'Umbral Camouflage', 3, ARRAY['theurge']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis: undetectable to spirit senses for the scene; any attack action breaks it. (W20 p. 165)'),
  ('36eec0f8-679a-559a-a58d-585bc99f31d4', NULL, 'Under the Gun', 3, ARRAY['shadow_lords']::text[], 'manipulation', 'firearms', 6, 0, 1, 0, 'Touch target, spend 1 Gnosis; Manipulation + Firearms: for a day per success, ranged attacks against them get -2 difficulty. (W20 p. 190)'),
  ('f13d22f8-c1c5-5a13-adc0-ee89abd71279', NULL, 'Venom Blood', 3, ARRAY['get_of_fenris']::text[], 'stamina', 'primal_urge', 7, 1, 0, 0, 'Spend 1 Rage; Stamina + Primal-Urge (diff 7): your blood is acidic for the scene, dealing aggravated damage per success to those it touches. (W20 p. 181)'),
  ('cec17d63-6bc1-5c27-aa97-0403e6745cfc', NULL, 'Visceral Agony', 3, ARRAY['black_furies']::text[], NULL, NULL, 6, 1, 0, 0, 'Spend 1 Rage before attacking; wound penalties you inflict are doubled for the scene, unless the target resists pain (e.g. frenzy). (W20 p. 174)'),
  ('ab6b87e1-00ce-5b13-9a25-9da560f2175a', NULL, 'Weak Arm', 3, ARRAY['philodox']::text[], 'perception', 'brawl', 8, 0, 0, 0, 'Perception + Brawl (diff 8), full turn: successes become bonus dice split across attack and damage vs one foe; once per foe per scene. (W20 p. 167)'),
  ('f8232823-1f76-5f64-be5c-caea9eccb1de', NULL, 'Web Walker', 3, ARRAY['theurge']::text[], 'charisma', 'science', 7, 0, 1, 0, 'Spend 1 Gnosis; Charisma + Science (diff 7): you and nearby pack travel the Umbra along the Pattern Web like a moon bridge. (W20 p. 165)'),
  ('253cf67d-3434-5477-8ccd-d27e3313578b', NULL, 'Wind Claws', 3, ARRAY['ahroun']::text[], NULL, NULL, 6, 1, 0, 0, 'Spend 1 Rage: for the turn, your natural attacks bypass all armor, so targets lose armor soak dice. (W20 p. 172)'),
  ('38ee8c35-d087-55ec-bb05-96df117f9382', NULL, 'Wind''s Returning Favor', 3, ARRAY['stargazers']::text[], 'dexterity', 'athletics', 6, 0, 0, 1, 'Spend 1 Willpower; Dexterity + Athletics vs close Melee attack: cancels their successes; surplus steals the weapon for next turn. (W20 p. 196)'),
  ('73cbdece-3bcb-5f68-a7ab-f979b96f01d5', NULL, 'Wings of Pegasus', 3, ARRAY['black_furies']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis (Hispo): wings give 50 mph flight until dismissed; fine maneuvers use Dexterity + Athletics at Storyteller difficulty. (W20 p. 174)'),
  ('209557e8-79bf-50fe-b243-cf0abecb0842', NULL, 'Wisdom of the Ancient Ways', 3, ARRAY['philodox','wendigo']::text[], 'gnosis', NULL, 6, 0, 0, 0, 'Meditate briefly, then roll Gnosis (diff 9, minus 1 per Ancestors dot): successes set the depth of ancestral knowledge gained. (W20 p. 167)'),
  ('10000000-0000-4000-8000-000000000318', NULL, 'Wrath of Gaia', 3, ARRAY['silver_fangs']::text[], 'charisma', 'intimidation', 6, 0, 1, 0, 'Spend 1 Gnosis; Charisma + Intimidation: Wyrm minions seeing you this scene must roll Willpower (diff 7) to match your successes or flee. (W20 p. 194)'),
  ('9d30447f-7ff6-5652-9886-4b4f7b9652aa', NULL, 'Yao''s Commands', 3, ARRAY['boli_zousizhe']::text[], 'charisma', 'subterfuge', 7, 0, 0, 0, 'Works as Elemental Favor; choose Eastern or urban elementals when learned, never both. (W20 p. 183)'),
  ('10000000-0000-4000-8000-000000000410', NULL, 'Attunement', 4, ARRAY['bone_gnawers','glass_walkers','silent_striders']::text[], 'perception', 'streetwise', 6, 0, 1, 0, 'Spend 1 Gnosis; Perception + Streetwise (diff 6): urban spirits reveal population, enclaves, tunnels; detail scales with successes. (W20 p. 176)'),
  ('10000000-0000-4000-8000-000000000412', NULL, 'Balor''s Gaze', 4, ARRAY['fianna']::text[], 'perception', 'occult', 8, 1, 1, 0, 'Spend 1 Rage + 1 Gnosis; Perception + Occult (diff 8): glared foes must beat successes on Willpower (diff 8) or take -5 Crippled penalty. (W20 p. 179)'),
  ('2589393a-b38c-59ea-80f5-9be70b957f01', NULL, 'Beast Life', 4, ARRAY['lupus','black_furies','children_of_gaia']::text[], 'charisma', 'animal_ken', 7, 0, 1, 0, 'Permanent animal speech; spend 1 Gnosis, Charisma + Animal Ken (diff 7) to summon animals within 10 miles per success who follow requests. (W20 p. 160)'),
  ('dd554433-41f2-54fb-812a-9e40cc9a21e6', NULL, 'Black Mark', 4, ARRAY['silent_striders']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis after a claw hit, before damage: target is haunted 1 day per damage level inflicted, like the Death-Wolf mark. (W20 p. 193)'),
  ('5fe831df-43b8-56f0-897e-fb8873ecac2b', NULL, 'Blink', 4, ARRAY['bone_gnawers']::text[], 'manipulation', 'stealth', 6, 0, 1, 0, 'Spend 1 Gnosis; Manipulation + Stealth (diff 6): teleport between shaded spots up to 20 yards per success. (W20 p. 176)'),
  ('efce0e37-7839-5b7d-bdb8-63fe8364e130', NULL, 'Blurring the Mirror', 4, ARRAY['theurge']::text[], NULL, NULL, 6, 0, 1, 0, 'No roll; spend 1 Gnosis per target (max 5): their local Gauntlet rises by 5 for the scene, blocking stepping sideways. (W20 p. 165)'),
  ('2535f493-42f7-5a75-9e7b-14e3811e02bd', NULL, 'Body Shift', 4, ARRAY['homid','ahroun','get_of_fenris']::text[], 'stamina', 'primal_urge', 9, 0, 0, 0, 'Stamina + Primal-Urge (diff 9): each 2 successes moves one physical Attribute dot to another physical Attribute for the scene. (W20 p. 154)'),
  ('d72f324d-9b31-5cec-ab9f-aec2b5b8a0f1', NULL, 'Body Wrack', 4, ARRAY['black_furies']::text[], 'gnosis', NULL, 6, 0, 1, 0, 'Spend 1 Gnosis; Gnosis roll: target stunned one round per success, plus -1 die on all rolls for the scene. (W20 p. 174)'),
  ('157e2983-74a0-5d56-869c-59d7fc97d1bc', NULL, 'Bridge Walker', 4, ARRAY['galliard']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis to make a personal one-use moon bridge up to Gnosis miles; +3 Willpower keeps it open until the next full moon. (W20 p. 170)'),
  ('2f228004-ca1c-5bbe-bb6b-b70ca4411855', NULL, 'Bury the Wolf', 4, ARRAY['homid']::text[], 'gnosis', NULL, 6, 0, 1, 0, 'Spend 1 Gnosis; Gnosis vs own Willpower: appear human to supernatural senses, no Curse or Rage, locked homid; duration by successes. (W20 p. 154)'),
  ('94a386ff-f2c1-58ae-b1f4-5e9d65d2fe2f', NULL, 'Call Elemental', 4, ARRAY['uktena']::text[], 'gnosis', NULL, 6, 0, 1, 0, 'Spend 1 Gnosis; Gnosis roll vs Gauntlet to summon an elemental, then Manipulation + Occult (diff 7) to win its help; it leaves at scene end. (W20 p. 198)'),
  ('b9da4cb8-4bbd-543b-9dcc-85b4534ea261', NULL, 'Call of the Cannibal Spirit', 4, ARRAY['wendigo']::text[], 'charisma', 'occult', 8, 1, 1, 0, 'Dance 3 turns, spend 1 Rage + 1 Gnosis; Charisma + Occult (diff 8): Wendigo avatar hunts a target; botch turns it on summoner. (W20 p. 201)'),
  ('10000000-0000-4000-8000-000000000421', NULL, 'Chill of Early Frost', 4, ARRAY['wendigo']::text[], 'intelligence', 'occult', 6, 0, 1, 0, 'Spend 1 Gnosis; Intelligence + Occult: 5-mile freeze, furless creatures -2 dice, lasts a day per success; diff 4 winter, 6 spring, 9 summer. (W20 p. 201)'),
  ('8b5efec9-7f0e-56d6-95a5-5f7236ddf4ca', NULL, 'Clenched Jaw', 4, ARRAY['ahroun','kucha_ekundu']::text[], NULL, NULL, 6, 1, 0, 0, 'After a bite hits, spend 1 Rage to hold on; later bites are diff 3, foes resist with Strength, and you add half Willpower (round up). (W20 p. 172)'),
  ('ce497d9b-4e5e-558c-adf6-a9848dead357', NULL, 'Cocoon', 4, ARRAY['homid']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis: sealed cocoon for a day, immobile and immune to environment; only damage of Stamina + Rituals or more breaks it. (W20 p. 155)'),
  ('dd03607a-c336-5fe3-9816-24a3d67da925', NULL, 'Dam the Heartflood', 4, ARRAY['silent_striders']::text[], 'manipulation', 'occult', 6, 0, 1, 0, 'Spend 1 Gnosis; Manipulation + Occult: for 1 turn per success target cannot use blood magic or spend blood points. (W20 p. 193)'),
  ('10000000-0000-4000-8000-000000000414', NULL, 'Doppelganger', 4, ARRAY['glass_walkers']::text[], 'charisma', 'performance', 8, 0, 1, 0, 'Spend 1 Gnosis; Charisma + Performance (diff 8): mimic a human, wolf or Garou''s looks, voice, scent for a day per success; traits unchanged. (W20 p. 184)'),
  ('c7391b2d-9a4a-5b6d-86db-72f1103b07c3', NULL, 'Durance', 4, ARRAY['shadow_lords','uktena']::text[], NULL, NULL, 6, 0, 1, 0, 'Reflexively spend 1 Gnosis when activating a talen to keep its spirit bound; fails on talens consumed by their use. (W20 p. 190)'),
  ('f6e358e4-935d-5595-8e2b-7a4e4ca9c3f6', NULL, 'Full Moon''s Light', 4, ARRAY['ahroun']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis, no roll: for the scene, enemies of you or your pack within 1 mile glow, defeating stealth and invisibility. (W20 p. 172)'),
  ('e97f258c-72d0-51cb-a2ca-affae16238df', NULL, 'Gift of Dreams', 4, ARRAY['galliard']::text[], 'wits', 'expression', 6, 0, 1, 0, 'Wits + Expression (diff 6) crafts a dream, better with more successes; breathe it into a sleeper''s mouth and spend 1 Gnosis to deliver. (W20 p. 170)'),
  ('063fd872-7d41-51d9-a501-6495181d3ddb', NULL, 'Gift of the Porcupine', 4, ARRAY['metis']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis (Crinos/Hispo/Lupus): quills deal Strength + 1 aggravated to grappled foes, Strength to weak bare-flesh hits; 1 scene. (W20 p. 157)'),
  ('10000000-0000-4000-8000-000000000403', NULL, 'Gnaw', 4, ARRAY['lupus']::text[], 'stamina', NULL, 6, 0, 0, 1, 'Spend 1 Willpower; Stamina + 4 vs material difficulty to chew through it; bite also gains +2 damage dice for the scene. (W20 p. 160)'),
  ('f5d86f0d-7285-5182-9780-5f292f6b57ec', NULL, 'Gorge', 4, ARRAY['red_talons']::text[], NULL, NULL, 6, 0, 0, 0, 'Permanent: pick Rage, Gnosis or Willpower to hold 3 points over permanent rating (no extra dice); each trait needs the Gift rebought. (W20 p. 187)'),
  ('10000000-0000-4000-8000-000000000405', NULL, 'Grasp the Beyond', 4, ARRAY['theurge']::text[], 'gnosis', NULL, 6, 0, 0, 1, 'Spend 1-3 Willpower by item size (1 small, 2 large, 3 person), then roll Gnosis to step sideways carrying it; unwilling targets resist. (W20 p. 165)'),
  ('10000000-0000-4000-8000-000000000420', NULL, 'Hand of the Earth Lords', 4, ARRAY['uktena']::text[], 'dexterity', 'occult', 7, 0, 1, 0, 'Spend 1 Gnosis; Dexterity + Occult (diff 7): telekinetically move an object up to 2,000 lbs at about 20 mph, 1 turn per success. (W20 p. 199)'),
  ('46e6b086-733d-5392-ab15-cf4a41560f3e', NULL, 'Heart of the Mountain', 4, ARRAY['get_of_fenris']::text[], NULL, NULL, 6, 1, 0, 1, 'Spend 1 Rage and 1 Willpower: for the scene Stamina tasks cannot fail, you can''t be broken or drowned, and you always soak at least 1 level. (W20 p. 181)'),
  ('10000000-0000-4000-8000-000000000413', NULL, 'Hero''s Stand', 4, ARRAY['get_of_fenris','wendigo']::text[], 'willpower', NULL, 8, 0, 0, 0, 'Willpower (diff 8): +1 die per success to Physical pools, cannot be surprised, attacks frontal; immobile until foes are beaten or flee. (W20 p. 181)'),
  ('d01efa1f-5859-51fc-a01a-35e8a3e7e2cd', NULL, 'Howl of Death', 4, ARRAY['red_talons']::text[], 'charisma', 'primal_urge', 6, 0, 0, 0, 'Charisma + Primal-Urge (diff 6): target who sees you and hears the howl takes 1 lethal per success, soakable. (W20 p. 187)'),
  ('e4444c4f-fea7-5e11-a8af-f00bc7500e91', NULL, 'Infest', 4, ARRAY['bone_gnawers']::text[], 'manipulation', 'animal_ken', 7, 0, 1, 0, 'Spend 1 Gnosis; Manipulation + Animal Ken (diff 7): vermin overrun a building; 5 successes make it uninhabitable. (W20 p. 176)'),
  ('5dee9fa1-0f66-556f-833d-9f4c5ae8fdb0', NULL, 'Lash of Rage', 4, ARRAY['metis']::text[], 'rage', NULL, 6, 1, 0, 0, 'Spend 1 Rage; roll Rage: target within 100 yards takes 1 unsoakable aggravated per success; repeat use in a scene also hurts you. (W20 p. 157)'),
  ('5ca944e1-600e-5c6a-a612-70a60c4057d2', NULL, 'Living Treasure', 4, ARRAY['hakken']::text[], 'manipulation', 'etiquette', 7, 0, 0, 0, 'Touch an object; Manipulation + Etiquette (diff 7): the item''s spirit shares one fact per success; once per object. (W20 p. 189)'),
  ('10000000-0000-4000-8000-000000000404', NULL, 'Luna''s Blessing', 4, ARRAY['ragabash']::text[], NULL, NULL, 6, 0, 0, 0, 'Passive while the moon is visible: silver deals lethal or bashing, not aggravated; silver attacks add an automatic 1 (two at full moon). (W20 p. 162)'),
  ('e4bfb976-5e5e-5509-9f39-0ab242737fbb', NULL, 'Mastery', 4, ARRAY['silver_fangs']::text[], 'charisma', 'leadership', 6, 0, 0, 0, 'Charisma + Leadership (diff target''s Wits + 3): give a Garou one non-suicidal command, obeyed 1 turn per success; Garou only. (W20 p. 194)'),
  ('10000000-0000-4000-8000-000000000418', NULL, 'Mindblock', 4, ARRAY['silver_fangs','stargazers']::text[], NULL, NULL, 6, 0, 0, 0, 'Permanent: mental control, mind-reading, illusions and possession against her are diff 10; emotion-altering magic is unaffected. (W20 p. 194)'),
  ('10000000-0000-4000-8000-000000000416', NULL, 'Open Wounds', 4, ARRAY['shadow_lords']::text[], 'strength', 'medicine', 7, 0, 1, 0, 'Spend 1 Gnosis; Strength + Medicine (diff 7): if your next attack hurts, target takes 1 unsoakable lethal per turn for successes-many turns. (W20 p. 190)'),
  ('be578f3a-0090-54f1-a3c4-bf6460a1be31', NULL, 'Phantasm', 4, ARRAY['fianna']::text[], 'intelligence', 'expression', 6, 0, 1, 0, 'Spend 1 Gnosis per 10-ft radius; Intelligence + Expression: static multisensory illusion; doubters need Perception + Alertness to beat you. (W20 p. 180)'),
  ('10000000-0000-4000-8000-000000000419', NULL, 'Preternatural Awareness', 4, ARRAY['stargazers']::text[], 'perception', 'athletics', 7, 0, 1, 0, 'Spend 1 Gnosis; Perception + Athletics (diff 7): enemies'' attack dice against you drop by your successes for the scene, even unseen attacks. (W20 p. 196)'),
  ('10000000-0000-4000-8000-000000000415', NULL, 'Quicksand', 4, ARRAY['red_talons']::text[], 'manipulation', 'primal_urge', 7, 0, 1, 0, 'Spend 1 Gnosis; Manipulation + Primal-Urge (diff 7): 10 ft bog radius, +10 ft per extra success; foes at half speed, maneuvers +1 diff. (W20 p. 187)'),
  ('f3f0fdba-8c6f-5f4c-9640-b5682a65b86a', NULL, 'Rattler''s Bite', 4, ARRAY['metis']::text[], NULL, NULL, 6, 1, 0, 0, 'Spend 1 Rage on a bite attempt; on a hit, damage remaining after soak is doubled. (W20 p. 157)'),
  ('c4247f08-b338-5ba2-815d-089eff480341', NULL, 'Roll Over', 4, ARRAY['philodox']::text[], 'willpower', NULL, 6, 0, 0, 0, 'Extended resisted Willpower contest per foe; a 3-success lead makes them submit, acting only with your leave for the scene. (W20 p. 167)'),
  ('2f07d36e-4ed0-5a0e-ba90-823827e41cf8', NULL, 'Scent of Beyond', 4, ARRAY['philodox']::text[], 'perception', 'enigmas', 8, 0, 0, 0, 'Perception + Enigmas (diff 8, or Gauntlet if higher in Umbra): project senses to a known place at will; -3 to local reactions meanwhile. (W20 p. 167)'),
  ('e1daa54b-d0f6-5de0-83bf-ceb3d30ce17a', NULL, 'Scream of Gaia', 4, ARRAY['lupus','get_of_fenris','wendigo']::text[], 'rage', NULL, 6, 0, 1, 0, 'Spend 1 Gnosis; Rage roll: all within 50 ft except pack are knocked down and take 1 unsoakable bashing level per success. (W20 p. 160)'),
  ('10000000-0000-4000-8000-000000000411', NULL, 'Serenity', 4, ARRAY['children_of_gaia']::text[], 'charisma', 'expression', 6, 0, 1, 0, 'Spend 1 Gnosis; Charisma + Expression: for 1 turn per success the target auto-fails Rage rolls, cannot frenzy or spend Rage. (W20 p. 178)'),
  ('10000000-0000-4000-8000-000000000407', NULL, 'Shadows by the Firelight', 4, ARRAY['galliard']::text[], 'manipulation', 'performance', 6, 0, 1, 0, 'Spend 1 Gnosis per unwilling target; Manipulation + Performance (diff Willpower): they join the tale for the scene or until attacked. (W20 p. 170)'),
  ('22b734c2-a849-5068-9958-dd68fbdf5475', NULL, 'Sidestep Death', 4, ARRAY['silver_fangs']::text[], NULL, NULL, 6, 0, 0, 3, 'Once per scene, spend 3 Willpower: evade one attack that would drop you below Crippled, teleporting to the nearest safe spot. (W20 p. 194)'),
  ('72b549ac-12a4-5907-ac57-a8a039e24824', NULL, 'Signal Rider', 4, ARRAY['glass_walkers']::text[], NULL, NULL, 6, 0, 1, 1, 'Spend 1 Willpower and 1 Gnosis to open a moon bridge along a phone link to the caller''s location, range Gnosis x 5 miles. (W20 p. 184)'),
  ('10000000-0000-4000-8000-000000000417', NULL, 'Speed Beyond Thought', 4, ARRAY['silent_striders']::text[], 'stamina', 'athletics', 7, 0, 1, 0, 'Spend 1 Gnosis; Stamina + Athletics (diff 7): run at 10x speed up to 8 hours, only able to run, then must eat or risk hunger frenzy. (W20 p. 193)'),
  ('8c837aa0-9086-5563-8c3b-f9a4f8f47dcc', NULL, 'Spirit Drain', 4, ARRAY['theurge']::text[], 'gnosis', NULL, 6, 0, 0, 0, 'Resisted Gnosis roll vs a spirit: it loses 1 Essence/success; each 2 drained gives you 1 temporary Willpower (excess lost at scene end). (W20 p. 165)'),
  ('10000000-0000-4000-8000-000000000401', NULL, 'Spirit Ward', 4, ARRAY['homid','theurge']::text[], 'manipulation', 'rituals', 7, 0, 1, 0, 'Spend 1 Gnosis; Manipulation + Rituals (diff 7): nearby spirits lose dice per success and close ones lose Essence each turn; one scene. (W20 p. 155)'),
  ('10000000-0000-4000-8000-000000000408', NULL, 'Stoking Fury''s Furnace', 4, ARRAY['ahroun']::text[], NULL, NULL, 6, 0, 0, 0, 'Permanent; no roll. Gain 1 Rage on any turn damaged (no frenzy check), and spending a single Rage per turn doesn''t drain temporary Rage. (W20 p. 172)'),
  ('6516ed41-9617-59fe-a183-f1254c4fb1e3', NULL, 'Strength of the Dominator', 4, ARRAY['shadow_lords']::text[], 'wits', 'intimidation', 6, 0, 0, 0, 'Wits + Intimidation: for turns equal to successes, target loses 1 Rage per turn and you gain it; once per target per scene. (W20 p. 191)'),
  ('9f6c5ec9-3cc9-574d-9c5b-b3eb42c3670b', NULL, 'Strike the Air', 4, ARRAY['children_of_gaia','stargazers']::text[], 'wits', 'athletics', 6, 0, 0, 1, 'Spend 1 Willpower; Wits + Athletics vs foe''s Willpower: that foe can''t hit you this scene; ends if you or allies attack; per-foe cost. (W20 p. 178)'),
  ('10000000-0000-4000-8000-000000000406', NULL, 'Take the True Form', 4, ARRAY['philodox']::text[], 'manipulation', 'primal_urge', 7, 0, 0, 0, 'Manipulation + Primal-Urge (diff 7): forces a shapechanger back to its natural form for 1 turn per success. (W20 p. 168)'),
  ('8250785c-3478-5906-ae2c-62e603853503', NULL, 'Tech Speak', 4, ARRAY['glass_walkers']::text[], 'charisma', 'science', 6, 0, 1, 0, 'Spend 1 Gnosis; Charisma + Science: relay a message via nearby tech, diff 4 (next room) to 9 (far); 1 success is a word, 5 is unlimited. (W20 p. 185)'),
  ('324d1e59-4745-5be8-8877-fa42313d581c', NULL, 'Terror of the Dire Wolf', 4, ARRAY['lupus']::text[], 'manipulation', 'primal_urge', 6, 1, 0, 0, 'Spend 1 Rage; Manipulation + Primal-Urge (diff target Willpower): Delirium hits all who see her, even mages; Homid/Glabro +1 diff. (W20 p. 160)'),
  ('162a4d6b-e036-5b43-8fda-eb0b56cbc997', NULL, 'Umbral Dodge', 4, ARRAY['ragabash']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis on a close-range dodge; difficulty +1 or local Gauntlet (higher); a full dodge drops the attacker across the Gauntlet. (W20 p. 162)'),
  ('40baf3eb-b24e-5548-b84a-ab7215d90b9c', NULL, 'Uncaught Since the Primal Morn', 4, ARRAY['children_of_gaia']::text[], 'stamina', 'athletics', 6, 0, 1, 0, 'Spend 1 Gnosis; Stamina + Athletics (diff = best pursuer''s Stamina + Athletics): outpaces all pursuers for 1 scene per success. (W20 p. 178)'),
  ('10000000-0000-4000-8000-000000000409', NULL, 'Wasp Talons', 4, ARRAY['black_furies']::text[], 'dexterity', 'brawl', 6, 1, 0, 0, 'Spend 1 Rage; Dexterity + Brawl, ranged like a firearm (medium range 20 yds): fire claws for normal claw damage; they regrow in 1 turn. (W20 p. 174)'),
  ('d47994e6-2c02-56c3-b7fc-250b0f290167', NULL, 'Whelp Body', 4, ARRAY['ragabash']::text[], 'gnosis', NULL, 6, 0, 1, 0, 'Spend 1 Gnosis; Gnosis roll vs target''s Gnosis/Stamina: each success permanently strips a Physical Attribute dot; once per victim ever. (W20 p. 162)'),
  ('10000000-0000-4000-8000-000000000402', NULL, 'Wither Limb', 4, ARRAY['metis']::text[], 'willpower', NULL, 6, 0, 1, 0, 'Spend 1 Gnosis; Willpower roll: victim gets +2 difficulty on Dexterity rolls; crippled leg halves speed. Regenerators recover after a scene. (W20 p. 157)'),
  ('24c0890d-5256-5c7a-aa33-81c1db56a034', NULL, 'Yu''s Endurance', 4, ARRAY['boli_zousizhe']::text[], NULL, NULL, 6, 1, 0, 1, 'Works exactly as Heart of the Mountain. (W20 p. 183)'),
  ('78b10a0e-7ae1-5de2-b341-2798eb0512f7', NULL, 'Assimilation', 5, ARRAY['homid']::text[], 'manipulation', 'empathy', 6, 0, 0, 0, 'Manipulation + Empathy: pass as a native of an alien culture, with its language, for a scene plus 1 day per Willpower spent. (W20 p. 155)'),
  ('26b59878-2d89-5d33-a6a7-458a1dd67e74', NULL, 'Beyond Human', 5, ARRAY['homid']::text[], NULL, NULL, 6, 0, 0, 0, 'Permanent, no roll: humans see you as impressive, not scary; spend Rage or Gnosis for +1 Social Attribute per point this scene (can pass 5). (W20 p. 155)'),
  ('5c7772d0-9ef6-53a9-9697-510230513b4b', NULL, 'Call the Hunt', 5, ARRAY['fianna']::text[], 'charisma', 'occult', 8, 0, 1, 0, 'After 1 hour chanting, spend 1 Gnosis; Charisma + Occult (diff 8): Huntsman arrives with 1 hound, +1 per extra Rage/Gnosis; may target you. (W20 p. 180)'),
  ('10000000-0000-4000-8000-000000000514', NULL, 'Chaos Mechanics', 5, ARRAY['glass_walkers']::text[], NULL, NULL, 6, 0, 0, 0, 'Permanent passive: you may use Rage and Gnosis in the same turn without penalty. (W20 p. 185)'),
  ('10000000-0000-4000-8000-000000000519', NULL, 'Circular Attack', 5, ARRAY['stargazers']::text[], 'wits', 'athletics', 6, 0, 0, 1, 'Spend 1 Willpower; Wits + Athletics (diff top foe Wits + 3): each success dodges or redirects an attack; once per turn, no Rage that turn. (W20 p. 196)'),
  ('08c04d27-8ffd-581b-b1ea-d41e19edd25d', NULL, 'Crocodile Pact', 5, ARRAY['kucha_ekundu']::text[], 'charisma', 'rituals', 7, 0, 2, 0, 'Spend 2 Gnosis; Charisma + Rituals (diff 7): Mokole-mbembe or ancestral spirits come to assist within the hour, as the Storyteller decides. (W20 p. 186)'),
  ('6063787e-9795-5d0d-9a4a-bb296cea6b8c', NULL, 'Curse of Lycaon', 5, ARRAY['red_talons']::text[], 'gnosis', NULL, 6, 0, 1, 0, 'Spend 1 Gnosis; Gnosis roll vs Willpower: a Garou target is locked in Lupus for the scene; a human or animal becomes a wolf permanently. (W20 p. 187)'),
  ('60f87d70-894d-5bbf-91a5-47dab002bd5f', NULL, 'Divine Wind', 5, ARRAY['hakken']::text[], 'stamina', 'enigmas', 7, 1, 0, 0, 'Stamina + Enigmas (diff 7), spend at least 1 Rage: storm of 1-mile radius per success, each extra Rage adds a success; one scene max. (W20 p. 189)'),
  ('92e30ddf-73b2-5955-9146-a25f832dd385', NULL, 'Elemental Gift', 5, ARRAY['lupus']::text[], 'gnosis', NULL, 8, 0, 1, 0, 'Spend 1 Gnosis; Gnosis (diff 8): summon an elemental to control about 20x20 ft of one element per success for the scene. (W20 p. 160)'),
  ('830f44f5-e383-5f9f-8781-acebfdd4b8a7', NULL, 'Endurance of Heimdall', 5, ARRAY['get_of_fenris']::text[], 'willpower', NULL, 6, 0, 2, 0, 'Spend 2 Gnosis; Willpower roll (diff 6): Stamina rating is doubled for the scene. (W20 p. 182)'),
  ('b6eac866-f8f9-5ded-91ae-f6149658d984', NULL, 'Fabric of the Mind', 5, ARRAY['galliard','uktena']::text[], 'intelligence', 'performance', 8, 0, 0, 0, 'Extended Intelligence + Performance (diff 8): conjure a creature with 1 trait dot per success; upkeep 1 Gnosis per scene. (W20 p. 170)'),
  ('10000000-0000-4000-8000-000000000513', NULL, 'Fenris'' Bite', 5, ARRAY['get_of_fenris']::text[], 'strength', 'primal_urge', 6, 1, 0, 0, 'Spend 1 Rage; Strength + Primal-Urge (diff foe Stamina + 3): next bite maims a limb for 3 unsoakable aggravated; 5+ successes severs. (W20 p. 182)'),
  ('10000000-0000-4000-8000-000000000505', NULL, 'Feral Lobotomy', 5, ARRAY['theurge']::text[], 'wits', 'empathy', 6, 0, 1, 0, 'Wits + Empathy (diff Willpower + 3, max 10); spend Gnosis (min 1): removes 1 permanent Intelligence per 2 Gnosis, capped by successes. (W20 p. 165)'),
  ('10000000-0000-4000-8000-000000000520', NULL, 'Fetish Doll', 5, ARRAY['uktena']::text[], 'perception', 'crafts', 8, 0, 0, 0, 'Week-long build via Perception + Crafts (diff 8); then Intelligence + Medicine vs victim''s Willpower: 1 soakable aggravated/success, max 10. (W20 p. 199)'),
  ('ade2bddf-5edc-5b4c-8ce4-b76bf6c693b1', NULL, 'Fog on the Moor', 5, ARRAY['fianna']::text[], 'gnosis', NULL, 7, 0, 0, 1, 'Spend 1 Willpower; Gnosis (diff 7): ghostly 1 turn per success, passes through matter, only silver harms; no regeneration meanwhile. (W20 p. 180)'),
  ('10000000-0000-4000-8000-000000000515', NULL, 'Gaia''s Vengeance', 5, ARRAY['red_talons']::text[], 'charisma', 'primal_urge', 6, 1, 1, 0, 'Spend 1 Gnosis and 1 Rage; Charisma + Primal-Urge: terrain attacks foes in ways the Storyteller decides. (W20 p. 187)'),
  ('23f58eac-412a-5d1a-9f66-caedec1ca9cc', NULL, 'Gate of the Moon', 5, ARRAY['silent_striders']::text[], 'intelligence', 'alertness', 6, 0, 1, 0, 'Spend 1 Gnosis per 100 miles; Intelligence + Alertness (diff by distance/familiarity): instant moon-bridge travel if moon is visible. (W20 p. 193)'),
  ('17655c22-efee-5306-b4db-0b33d44cdf9c', NULL, 'Geas', 5, ARRAY['philodox']::text[], 'manipulation', 'leadership', 6, 0, 1, 0, 'Spend 1 Gnosis; Manipulation + Leadership: bind target or group to complete a task until done or incapacitated pursuing it. (W20 p. 168)'),
  ('10000000-0000-4000-8000-000000000512', NULL, 'Gift of the Spriggan', 5, ARRAY['fianna']::text[], 'stamina', 'primal_urge', 8, 0, 1, 0, 'Spend 1 Gnosis; Stamina + Primal-Urge (diff 8): resize 1 hour per success; growing gives +3 Strength dice per doubling. (W20 p. 180)'),
  ('10000000-0000-4000-8000-000000000509', NULL, 'Gorgon''s Gaze', 5, ARRAY['black_furies']::text[], 'appearance', 'occult', 6, 0, 1, 0, 'Spend 1 Gnosis after eye contact; Appearance + Occult vs Willpower: target paralyzed 1 turn per success; 5 successes petrify permanently. (W20 p. 174)'),
  ('10000000-0000-4000-8000-000000000511', NULL, 'Halo of the Sun', 5, ARRAY['children_of_gaia']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis: scene-long sunlight aura; Homid/Glabro melee +2 dice and aggravated, foes +3 attack difficulty, vampires nearby burn. (W20 p. 178)'),
  ('4341a8f8-9467-534d-8cae-8d42c7a56bd5', NULL, 'Harmonious Unity of the Emerald Mother', 5, ARRAY['stargazers']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis: for a day, Homid form gains Crinos Attribute bonuses and regeneration, but no claws, fangs, senses or Delirium. (W20 p. 196)'),
  ('b5c468b7-a96c-525f-b492-0650340f0db3', NULL, 'Head Games', 5, ARRAY['galliard']::text[], 'manipulation', 'empathy', 6, 0, 0, 0, 'Manipulation + Empathy vs target''s Willpower: steer one target''s emotions as you wish for the scene. (W20 p. 170)'),
  ('10000000-0000-4000-8000-000000000521', NULL, 'Heart of Ice', 5, ARRAY['wendigo']::text[], 'wits', 'occult', 6, 0, 1, 0, 'Spend 1 Gnosis; Wits + Occult vs Willpower: each success is 1 unsoakable aggravated level, dealt at 1 level per turn. (W20 p. 201)'),
  ('0500c8ae-2c2f-5403-95b6-991ea1a3a2cc', NULL, 'Horde of Valhalla', 5, ARRAY['get_of_fenris']::text[], 'charisma', 'animal_ken', 6, 0, 0, 0, 'Spend any Rage and Gnosis; Charisma + Animal Ken (diff 6): one Great Wolf per point spent, using Wild Hunt hound stats, for the scene. (W20 p. 182)'),
  ('313e2a12-82b5-5324-ad06-6a4754368c74', NULL, 'Huang Di''s Sacrifice', 5, ARRAY['boli_zousizhe']::text[], 'stamina', 'leadership', 8, 0, 2, 0, 'Spend 2 Gnosis; Stamina + Leadership (diff 8): each success lets one packmate heal that many health levels, aggravated included. (W20 p. 183)'),
  ('5792b3b1-b91d-53f2-8b54-4b1516c99f18', NULL, 'Invoke the Spirits of the Storm', 5, ARRAY['wendigo']::text[], 'willpower', NULL, 6, 0, 1, 0, 'Spend 1 Gnosis; roll Willpower: summon weather over 10 miles per success; a thunderstorm allows Gnosis-fueled 10-die aggravated lightning. (W20 p. 201)'),
  ('10000000-0000-4000-8000-000000000508', NULL, 'Kiss of Helios', 5, ARRAY['ahroun']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis: scene-long fire immunity; artificial/magical flame does max 1 bashing per turn; burning attacks add 2 aggravated dice. (W20 p. 172)'),
  ('10000000-0000-4000-8000-000000000518', NULL, 'Luna''s Avenger', 5, ARRAY['silver_fangs']::text[], NULL, NULL, 6, 0, 1, 0, 'After a turn of focus, spend 1 Gnosis: for the scene you ignore silver, your body strikes count as silver, +2 Stamina, +1 health level. (W20 p. 194)'),
  ('10000000-0000-4000-8000-000000000502', NULL, 'Madness', 5, ARRAY['metis']::text[], 'manipulation', 'intimidation', 6, 0, 1, 0, 'Spend 1 Gnosis; Manipulation + Intimidation: target gains a Derangement lasting days equal to successes, severity adjustable by user. (W20 p. 157)'),
  ('59aa5b4e-27b3-5632-9de7-92f64011eb6e', NULL, 'Malleable Spirit', 5, ARRAY['theurge']::text[], 'gnosis', NULL, 6, 0, 0, 0, 'Resisted Gnosis roll vs. spirit (its difficulty = your Gnosis): alter its traits (diff 6), disposition (7) or type (9). (W20 p. 166)'),
  ('9bd8bb29-f694-5a61-b678-44bb7c0b69ce', NULL, 'Mask Taint', 5, ARRAY['skin_dancer']::text[], 'perception', 'subterfuge', 8, 0, 1, 0, 'Spend 1 Gnosis; Perception + Subterfuge (diff 8): hide Wyrm taint from all detection for 1 scene per success. (W20 p. 199)'),
  ('c10c5419-4562-5214-8476-6fc1acdc25ed', NULL, 'Obedience', 5, ARRAY['shadow_lords']::text[], 'charisma', 'leadership', 8, 0, 1, 0, 'Spend 1 Gnosis; Charisma + Leadership (diff 8): nearby must match with Willpower (diff 8) or obey for a day, severity scaling by margin. (W20 p. 191)'),
  ('10000000-0000-4000-8000-000000000501', NULL, 'Part the Veil', 5, ARRAY['homid']::text[], 'charisma', 'empathy', 6, 0, 1, 0, 'Spend 1 Gnosis; Charisma + Empathy, one success needed: a human resists the Delirium for the scene but may lose memories later. (W20 p. 155)'),
  ('aae74926-f0f4-59f9-a017-53aa27961d04', NULL, 'Paws of the Newborn Cub', 5, ARRAY['silver_fangs']::text[], 'gnosis', NULL, 6, 0, 2, 0, 'Spend 2 Gnosis; Gnosis roll vs Willpower: target loses all supernatural powers for 1 turn per success. (W20 p. 195)'),
  ('bc1a1718-c41c-54cd-8694-604193a0f9b7', NULL, 'Protean Form', 5, ARRAY['metis']::text[], NULL, NULL, 6, 0, 0, 0, 'Permanent. Custom partial-shift body parts give +2 dice or +2 damage on an attack category, or +5 yards/turn movement. (W20 p. 157)'),
  ('10000000-0000-4000-8000-000000000517', NULL, 'Reach the Umbra', 5, ARRAY['silent_striders']::text[], NULL, NULL, 6, 0, 0, 0, 'No roll: step sideways instantly at will; rolls to cross realms get -2 difficulty; no Rage spend that turn and can''t dodge declared attacks. (W20 p. 193)'),
  ('10000000-0000-4000-8000-000000000510', NULL, 'Riot', 5, ARRAY['bone_gnawers']::text[], 'wits', 'subterfuge', 8, 0, 1, 0, 'Spend 1 Gnosis; Wits + Subterfuge (diff 8): spirits incite a riot against your chosen target across a radius of 1 mile per success. (W20 p. 176)'),
  ('94d94a48-462d-5a75-9240-41cabb95dae3', NULL, 'Scabwalker Curse', 5, ARRAY['red_talons']::text[], 'manipulation', 'survival', 7, 0, 1, 0, 'Snarl a turn at target within 20 ft, 1 Gnosis; Manipulation + Survival (diff 7): 1 bashing/turn touching artificial matter; 1 day/success. (W20 p. 187)'),
  ('bae3d3fe-96f6-5dda-8fe7-48f13610edc7', NULL, 'Shadow Pack', 5, ARRAY['shadow_lords']::text[], 'gnosis', NULL, 8, 0, 1, 0, 'Gnosis roll (diff 8), spend Gnosis (min 1): one shadow double per point with her traits but no Gifts or pools, 1 health level, scene-long. (W20 p. 191)'),
  ('10000000-0000-4000-8000-000000000503', NULL, 'Song of the Great Beast', 5, ARRAY['lupus']::text[], 'charisma', 'primal_urge', 8, 0, 2, 0, 'Spend 2 Gnosis; Charisma + Primal-Urge (diff 8): a prehistoric Great Beast arrives and grants a request its own way; successes aid mood. (W20 p. 160)'),
  ('da8d3d05-f245-5739-b4dd-337f81b767e5', NULL, 'Strength of Will', 5, ARRAY['ahroun']::text[], 'charisma', 'leadership', 8, 0, 0, 1, 'Spend 1 Willpower; Charisma + Leadership (diff 8): each success gives allies a temporary Willpower point for the scene; once per scene. (W20 p. 172)'),
  ('d2ffedea-5e56-5b68-a0a7-123cc5039f1a', NULL, 'Summon Net-Spider', 5, ARRAY['glass_walkers']::text[], 'charisma', 'computer', 8, 0, 1, 0, 'Spend 1 Gnosis; Charisma + Computer (diff 8): summons a spirit that wrecks a computer; permanently halves difficulty of computer rolls. (W20 p. 185)'),
  ('5020e2d9-4fd5-53b9-b722-a740c8495d5d', NULL, 'Survivor', 5, ARRAY['bone_gnawers']::text[], 'stamina', 'survival', 6, 0, 1, 0, 'Spend 1 Gnosis; Stamina + Survival: no food, water, sleep needs; resists weather, disease, poison 1 day per success. (W20 p. 176)'),
  ('33a25ab4-81f6-54e3-96c5-f6d740da8ef1', NULL, 'The Living Wood', 5, ARRAY['children_of_gaia']::text[], 'charisma', 'survival', 8, 0, 1, 0, 'Spend 1 Gnosis; Charisma + Survival (diff 8): animates one nearby tree per success to protect and fight for you. (W20 p. 178)'),
  ('10000000-0000-4000-8000-000000000504', NULL, 'Thieving Talons of the Magpie', 5, ARRAY['ragabash']::text[], 'wits', 'larceny', 6, 0, 0, 0, 'Wits + Larceny, needs 3 successes: steal a known power from a target; keep it by paying 1 Gnosis per turn, using your Gnosis for its traits. (W20 p. 163)'),
  ('55b76709-d795-509b-8736-e149b9cd4e75', NULL, 'Thousand Forms', 5, ARRAY['ragabash','black_furies']::text[], 'intelligence', 'animal_ken', 6, 0, 1, 0, 'Spend 1 Gnosis; Intelligence + Animal Ken (diff 6): take any normal animal shape for the scene; mythical forms cost +1 Gnosis at diff 9. (W20 p. 163)'),
  ('4b6af5d9-6147-5b9e-84e6-68ba1ea9dca9', NULL, 'Totem Gift', 5, ARRAY['metis']::text[], 'charisma', 'rituals', 7, 0, 1, 0, 'Spend 1 Gnosis; Charisma + Rituals (diff 7): tribal totem sends aid whose scale grows with successes, from a nuisance to catastrophe. (W20 p. 158)'),
  ('5faebe79-2250-5e65-a511-c97e6ca384ab', NULL, 'Ultimate Argument of Logic', 5, ARRAY['theurge']::text[], 'manipulation', 'performance', 6, 0, 0, 0, 'Manipulation + Performance needing 3 successes: target firmly believes one chosen fact about existence. (W20 p. 166)'),
  ('10000000-0000-4000-8000-000000000506', NULL, 'Wall of Granite', 5, ARRAY['philodox']::text[], NULL, NULL, 6, 0, 1, 0, 'Spend 1 Gnosis on earth: mobile stone wall (soak 10, 15 levels to breach) covers you and up to Gnosis allies for a scene. (W20 p. 168)'),
  ('37b2fc52-0a5d-5034-a2c7-aaf38c24d7af', NULL, 'Wisdom of the Seer', 5, ARRAY['stargazers']::text[], 'intelligence', 'enigmas', 7, 0, 1, 0, 'After an hour of stargazing, spend 1 Gnosis; Intelligence + Enigmas (diff 7): Storyteller answers one question, clearer with more successes. (W20 p. 196)'),
  ('88d74b78-07bc-5952-bab4-4afd85e46634', NULL, 'Wyld Warp', 5, ARRAY['black_furies']::text[], 'wits', 'enigmas', 6, 1, 1, 0, 'Spend 1 Gnosis and 1 Rage; Wits + Enigmas: successes call a variable number of Wyldlings who cause unpredictable helpful chaos. (W20 p. 174)'),
  ('2ded2ca8-770e-5265-af97-56ffdda2ce65', NULL, 'As In the Beginning', 6, ARRAY['theurge']::text[], 'wits', 'occult', 6, 0, 3, 0, 'Spend 3 Gnosis; Wits + Occult vs local Gauntlet: Gauntlet falls in an area, allies arrive, area stays 1 lower (no stacking). (W20 p. 166)'),
  ('18170a81-c214-59c5-8bbe-3c2e450c0775', NULL, 'Break the Bonds', 6, ARRAY['philodox','galliard']::text[], NULL, NULL, 6, 0, 0, 0, 'No activation roll: immune to coercion; Strength 15 vs restraints; Manipulation + Leadership (11 - Willpower) frees minds. (W20 p. 168)'),
  ('10ad8016-cd84-5655-acdb-b9760e852d76', NULL, 'Call Great Fenris', 6, ARRAY['get_of_fenris']::text[], 'stamina', 'occult', 6, 0, 1, 0, 'Spend 1 Gnosis; Stamina + Occult (diff 6): summon Great Fenris''s war-avatar to fight for you, at the price of a sacrifice. (W20 p. 182)'),
  ('31a4ac46-7ac1-5910-a429-6e6e73fb143a', NULL, 'Firebringer', 6, ARRAY['ragabash']::text[], NULL, NULL, 6, 0, 0, 0, 'No roll; after a power is used on you, spend 1 permanent Gnosis to turn it into a teachable Gift; you lose defenses against it. (W20 p. 163)'),
  ('f933d93a-9397-521a-a04e-36b49b6b4f41', NULL, 'Renew the Cycle', 6, ARRAY['silver_fangs']::text[], 'gnosis', NULL, 8, 0, 1, 0, 'Resisted Gnosis vs Willpower (both diff 8): a win destroys an undead; costs 1 Gnosis per century of its age, permanent Gnosis if needed. (W20 p. 195)'),
  ('7cbe9ccd-b854-5dfa-9153-5b5c3b7ebb8c', NULL, 'Shield of Gaia', 6, ARRAY['red_talons']::text[], NULL, NULL, 6, 0, 0, 0, 'Permanent: pick one Weaver technology (bullets, cameras, electricity, toxins, etc.) at purchase and become immune to it. (W20 p. 188)'),
  ('c8de283f-ae90-5a23-9806-023731fbec31', NULL, 'Unstoppable Warrior', 6, ARRAY['ahroun']::text[], NULL, NULL, 6, 0, 0, 0, 'Permanent passive: you heal aggravated damage as if it were lethal, except damage from silver. (W20 p. 172)')
